\label{R-embedding}
The following consequences are useful for the subsequent sections:
\begin{enumerate}
\item[(a)]\,\,\,If $p=2$, then it is obvious that the inequalities (\ref{2.03}), (\ref{2.04}), (\ref{2.04b}), (\ref{2.05}), and (\ref{2.06}),
are valid if one replace the space $H^{1}(\Omega)$ by the space $H^1_{\mu}(\Omega;\Gamma)$.
\item[(b)]\,\,\,If $\Omega\subseteq\mathbb{R\!}^N$ is a bounded $W^{1,p}$-extension domain
and $\mu$ is an upper-$d$-Ahlfors measure supported on $\Gamma$, then from (\ref{2.04}) together with an argument in
\cite[Theorem 4.24]{BIE10.1}, it follows that the norm
$$|\|u\||^p_{_{\mathcal{W}^{1,p}(\Omega)}}:=\|\nabla u\|^p_{_{p,\Omega}}+\left\|u|_{_{\Gamma}}\right\|^p_{_{p,\Gamma}}$$
is an equivalent norm for $W^{1,p}(\Omega)$.
\item[(c)]\,\,\,From (\ref{2.06}), it follows immediately that there exists a constant $c_{6}>0$ such that
\begin{equation}\label{2.07}
\|u\|_{_{W^{1,p}(\Omega)/\mathbb{R\!}}}\,\leq\,\|u\|_{_{W^{1,p}(\Omega)}}\,\leq\,c_{6}\|u\|_{_{W^{1,p}(\Omega)/\mathbb{R\!}}},
\end{equation}
for every $u\in W_0(\Omega)$.
\item[(d)]\,\,\,Let $p\in(1,N)$. Then, in views of \cite[Lemma 4.3]{GES-MITR09} (see also \cite[Lemma 2.4.7]{NITTKA2010}),
given $\epsilon>0$, there exists constants $C_{\epsilon},\,C'_{\epsilon}>$ such that
\begin{equation}\label{epsilon-interior}
\|u\|_{_{r,\Omega}}\,\leq\,\epsilon\|\nabla u\|_{_{p,\Omega}}+C_{\epsilon}\|u\|_{_{p,\Omega}}
\end{equation}
and
\begin{equation}\label{epsilon-trace}
\|u\|_{_{s,\Gamma}}\,\leq\,\epsilon\|\nabla u\|_{_{p,\Omega}}+C'_{\epsilon}\|u\|_{_{p,\Omega}},
\end{equation}
for each $u\in W^{1,p}(\Omega)$, whenever $1\leq r<Np(N-p)^{-1}$ and $1\leq s<dp(N-p)^{-1}$. Furthermore, by easily extending the results in \cite[Proposition 2.1]{Winkert-2014} and \cite[Theorem 2.3]{Winkert-Zacher-2016}, one sees that
$C_{\epsilon}=c\epsilon^{^{-\frac{Nr-Np}{rp-Nr+Np}}}$ and $C'_{\epsilon}=c'\epsilon^{^{-\frac{Ns-dp}{sp-Ns+dp}}}$ for some positive constants $c,\,c'$.
\end{enumerate}

\label{As1}
Given $N\geq2,\,\,\mathfrak{s}\in(0,1),\,\,d\in (N-2,N)\cap(0,N)$, and $r_d:=2-N+d$,
let $\Omega\subseteq\mathbb{R\!}^N$ be a bounded extension domain,
and let $\mu$ be an upper $d$-Ahlfors measure supported on the boundary
$\Gamma:=\partial\Omega$.

\label{cont-coercive-form}
The form $(\mathcal{E}_{\mu},\mathcal{W}_2(\Omega;\Gamma))$ is continuous and weakly coercive. Consequently, if
$(f,g)\in\mathbb{X\!}^{\,p,q}(\Omega;\Gamma)$ for $p\geq(2^{\ast}_{_N})'$ and $q\geq(2^{\ast}_{_d})'$, where
\begin{equation}\label{linear-critical-exp}
2^{\ast}_{_N}:=\left\{\begin{array}{lcl}
\frac{2N}{N-2},\indent\indent\,\,\,\textrm{if}\,\,\,N>2,\\[1ex]
r\in[2,\infty),\,\,\,\,\,\,\,\,\textrm{if}\,\,\,N=2,\\[1ex]
\end{array}
\right.\,\,\,\textrm{and}\,\,\,\,\, 2^{\ast}_{_d}:=\left\{\begin{array}{lcl}
\frac{2d}{N-2},\indent\indent\,\,\,\textrm{if}\,\,\,N>2,\\[1ex]
r\in[2,\infty),\,\,\,\,\,\,\,\,\textrm{if}\,\,\,N=2,\\[1ex]
\end{array}
\right.
\end{equation}
then there exists an unique function $u\in\mathcal{W}_2(\Omega;\Gamma))$, and there exists a constant $\delta^{\star}_0\geq0$, such that
\begin{equation}\label{cc00}
\mathcal{E}_{\mu}(u,\varphi)+\delta^{\star}_0\displaystyle\int_{\Omega}u\varphi\,dx=\displaystyle\int_{\Omega}f\varphi\,dx+
\displaystyle\int_{\Gamma}g\varphi\,d\mu\,,\indent\,\,\textrm{for all}\,\,\varphi\in\mathcal{W}_2(\Omega;\Gamma).
\end{equation}

We assume that condition {\bf (C2)} holds (the other cases are simpler), and take $u,\,v\in\mathcal{W}_2(\Omega;\Gamma))$.
Also for simplicity, we prove the result for $N>2$.
Then in views of (\ref{2.03}) together with H\"older's inequality (when necessary),
we get the following calculations over each of the integral terms of the form $\mathcal{E}_{\mu}(\cdot,\cdot)$:\\[2ex]
$\left|\displaystyle\int_{\Omega}\displaystyle\sum^N_{^{i=1}}\hat{a}_i(x)u\partial_{x_i}v\,dx\right|\,\leq\,\|\hat{\mathfrak{a}}\|_{_{N,\Omega}}\|u\nabla v\|_{_{\frac{N}{N-1},\Omega}}$\\
\begin{equation}\label{cc01}
\leq\,|\Omega|^{^{\frac{1}{N}-\frac{1}{r_1}}}\|\hat{\mathfrak{a}}\|_{_{r_1,\Omega}}\|u\|_{_{\frac{2N}{N-2},\Omega}}\|\nabla v\|_{_{2,\Omega}}
\,\leq\,C_1|\Omega|^{^{\frac{1}{N}-\frac{1}{r_1}}}\|\hat{\mathfrak{a}}\|_{_{r_1,\Omega}}\|u\|_{_{\mathcal{W}_2(\Omega;\Gamma)}}\|v\|_{_{\mathcal{W}_2(\Omega;\Gamma)}},
\end{equation}
for some constant $C_1>0$. Similarly, we have
\begin{equation}\label{cc02}
\left|\displaystyle\int_{\Omega}\displaystyle\sum^N_{^{i=1}}\check{a}_i(x)\partial_{x_i}uv\,dx\right|
\,\leq\,C_2|\Omega|^{^{\frac{1}{N}-\frac{1}{r_2}}}\|\check{\mathfrak{a}}\|_{_{r_2,\Omega}}\|u\|_{_{\mathcal{W}_2(\Omega;\Gamma)}}\|v\|_{_{\mathcal{W}_2(\Omega;\Gamma)}},
\end{equation}
for some constant $C_2>0$. In the same way, using (\ref{2.03}) and (\ref{2.04}), we get the existence of constants $C_3,\,C_4>0$, such that\\[2ex]
$\left|\displaystyle\int_{\Omega}\lambda uv\,dx\right|\,\leq\,|\Omega|^{^{1-\frac{1}{r_3}-\frac{N-2}{N}}}\|\lambda\|_{_{r_3,\Omega}}\|uv\|_{_{\frac{N}{N-2},\Omega}}$\\
\begin{equation}\label{cc03}
\leq\,|\Omega|^{^{1-\frac{1}{r_3}-\frac{N-2}{N}}}\|\lambda\|_{_{r_3,\Omega}}\|u\|_{_{\frac{2N}{N-2},\Omega}}\|v\|_{_{\frac{2N}{N-2},\Omega}}\,
\leq\,C_3|\Omega|^{^{1-\frac{1}{r_3}-\frac{N-2}{N}}}\|\lambda\|_{_{r_3,\Omega}}\|u\|_{_{\mathcal{W}_2(\Omega;\Gamma)}}\|v\|_{_{\mathcal{W}_2(\Omega;\Gamma)}},
\end{equation}
and\\[2ex]
$\left|\displaystyle\int_{\Gamma}\beta uv\,d\mu\right|\,\leq\,\mu(\Gamma)^{^{1-\frac{1}{s}-\frac{N-2}{d}}}\|\beta\|_{_{s,\Gamma}}\|uv\|_{_{\frac{d}{N-2},\Gamma}}$\\
\begin{equation}\label{cc04}
\leq\,\mu(\Gamma)^{^{1-\frac{1}{s}-\frac{N-2}{d}}}\|\beta\|_{_{s,\Gamma}}\|u\|_{_{\frac{2d}{N-2},\Omega}}\|v\|_{_{\frac{2d}{N-2},\Omega}}\,
\leq\,C_4\mu(\Gamma)^{^{1-\frac{1}{s}-\frac{N-2}{d}}}\|\beta\|_{_{s,\Gamma}}\|u\|_{_{\mathcal{W}_2(\Omega;\Gamma)}}\|v\|_{_{\mathcal{W}_2(\Omega;\Gamma)}}.
\end{equation}
Now, applying (\ref{2.04b} and (\ref{2.05}), we see that
\begin{equation}\label{cc05}
\left|\left\langle\mathcal{J}_{_{\Omega}}u,v\right\rangle_{s/2}\right|\,\leq\,c\|u\|_{_{H^{s/2}(\Omega)}}\|v\|_{_{H^{s/2}(\Omega)}}\,\leq\,
C_5\|u\|_{_{\mathcal{W}_2(\Omega;\Gamma)}}\|v\|_{_{\mathcal{W}_2(\Omega;\Gamma)}},
\end{equation}
and
\begin{equation}\label{cc06}
\left|\left\langle\Theta_{_{\Gamma}}u,v\right\rangle_{r_d/2}\right|\,\leq\,c'\|u\|_{_{H^{r_d/2}_{\mu}(\Gamma)}}\|v\|_{_{H^{r_d/2}_{\mu}(\Gamma)}}\,\leq\,
C_6\|u\|_{_{\mathcal{W}_2(\Omega;\Gamma)}}\|v\|_{_{\mathcal{W}_2(\Omega;\Gamma)}},
\end{equation}
for some constants $c,\,c',\,C_5,\,C_6>0$. Furthermore, since the ``Wentzell-type" form $\Lambda_{_{\Gamma}}(\cdot,\cdot)$ is assumed to be continuous,
this means that there exists constants $c'',\,C_7>0$, such that
\begin{equation}\label{cc07}
\left|\Lambda_{_{\Gamma}}(u,v)\right|\,\leq\,c''\|u\|_{_{D(\Lambda_{_{\Gamma}})}}\|v\|_{_{D(\Lambda_{_{\Gamma}})}}\,\leq\,
C_7\|u\|_{_{\mathcal{W}_2(\Omega;\Gamma)}}\|v\|_{_{\mathcal{W}_2(\Omega;\Gamma)}}.
\end{equation}
Obviously
\begin{equation}\label{cc08}
\left|\displaystyle\int_{\Omega}\displaystyle\sum^N_{^{i,j=1}}\alpha_{ij}(x)\partial_{x_j}u\partial_{x_i}v\,dx\right|\,\leq\,C_8\|\bar{\alpha}\|_{_{\infty,\Omega}}
\|u\|_{_{\mathcal{W}_2(\Omega;\Gamma)}}\|v\|_{_{\mathcal{W}_2(\Omega;\Gamma)}},
\end{equation}
and therefore (\ref{cc01}), (\ref{cc02}), (\ref{cc03}), (\ref{cc04}), (\ref{cc05}), (\ref{cc06}), (\ref{cc07}),(\ref{cc08}), show that
the form $(\mathcal{E}_{\mu},D(\mathcal{E}_{\mu}))$ is continuous (possibly nonlocal, depending on the selection of the operators $\mathcal{J}_{_{\Omega}}$ and
$\Theta_{_{\Gamma}}$). To show the weak coercivity of $\mathcal{E}_{\mu}(\cdot,\cdot)$, we first recall that $\langle\mathcal{J}_{_{\Omega}}u,u\rangle_{s/2}\geq0$,\,
$\langle\Theta_{_{\Gamma}}v,v\rangle_{r_d/2}\geq0$. Also we recall that $\Lambda_{_{\Gamma}}(\cdot,\cdot)$ is weakly coercive, which
means that there exist constants $c^{\star}_0>0$ and $\gamma_0\in\mathbb{R\!\,}$ such that
\begin{equation}\label{Wentzell-weak-coercive}
c^{\star}_0\|u\|^2_{_{D(\Lambda_{_{\Gamma}})}}\,\leq\,\Lambda_{_{\Gamma}}(u,u)+\gamma_0\|u\|^2_{_{2,\Gamma}}.
\end{equation}
Consequently, taking into account (\ref{1.04}), we get that\\[2ex]
\indent$\min\{c_0,c^{\star}_0\}\|u\|^2_{_{\mathcal{W}_2(\Omega;\Gamma)}}\,\leq\,\mathcal{E}_{\mu}(u,u)+\gamma_0\displaystyle\int_{\Gamma}u^2\,d\mu+
\left|\displaystyle\int_{\Omega}\displaystyle\sum^N_{^{i=1}}\hat{a}_i(x)u\partial_{x_i}u\,dx\right|+$
\begin{equation}\label{cc09}
\indent\indent\indent+\left|\displaystyle\int_{\Omega}\displaystyle\sum^N_{^{i=1}}\check{a}_i(x)\partial_{x_i}u\,u\,dx\right|+
\left|\displaystyle\int_{\Omega}(\lambda+c_0) u^2\,dx\right|+\left|\displaystyle\int_{\Gamma}\beta u^2\,d\mu\right|.
\end{equation}
Now, since $\min\{r_1,r_2\}>N$, we have that the embedding maps $\mathcal{W}_2(\Omega;\Gamma)\hookrightarrow L^{^{\frac{2r_1}{r_1-2}}}(\Omega)$ and
$\mathcal{W}_2(\Omega;\Gamma)\hookrightarrow L^{^{\frac{2r_2}{r_2-2}}}(\Omega)$ are compact, so using this together with
Remark \ref{R-embedding}(d), we apply H\"older's inequality and Young's inequality to produce the following calculations:\\[2ex]
$\left|\displaystyle\int_{\Omega}\displaystyle\sum^N_{^{i=1}}\hat{a}_i(x)u\partial_{x_i}u\,dx\right|\,\leq\,
\|\hat{\mathfrak{a}}\|_{_{r_1,\Omega}}\|u\|_{_{\frac{2r_1}{r_1-2},\Omega}}\|\nabla u\|_{_{2,\Omega}}$\\
$$\leq\,\|\hat{\mathfrak{a}}\|_{_{r_1,\Omega}}\left(\epsilon_1\|\nabla u\|^2_{_{2,\Omega}}+
\epsilon^{-1}_1\|u\|^2_{_{\frac{2r_1}{r_1-2},\Omega}}\right)\,\leq\,\|\hat{\mathfrak{a}}\|_{_{r_1,\Omega}}\left(2\epsilon_1\|\nabla u\|^2_{_{2,\Omega}}+
\frac{C_{\epsilon^2_1}}{\epsilon_1}\|u\|^2_{_{2,\Omega}}\right)$$
\begin{equation}\label{cc10}
\indent\indent\indent\indent\,\,\,\,\,\,\indent\leq\,\|\hat{\mathfrak{a}}\|_{_{r_1,\Omega}}\left(2\epsilon_1
\|u\|^2_{_{\mathcal{W}_2(\Omega;\Gamma)}}+\frac{C_{\epsilon^2_1}}{\epsilon_1}\|u\|^2_{_{2,\Omega}}\right),
\end{equation}
for all $\epsilon_1>0$, and for some constant $C_{\epsilon^2_1}>0$. In the exact way, we get that
\begin{equation}\label{cc11}
\left|\displaystyle\int_{\Omega}\displaystyle\sum^N_{^{i=1}}\check{a}_i(x)\partial_{x_i}u\,u\,dx\right|
\leq\,\|\check{\mathfrak{a}}\|_{_{r_2,\Omega}}\left(2\epsilon_2
\|u\|^2_{_{\mathcal{W}_2(\Omega;\Gamma)}}+\frac{C_{\epsilon^2_2}}{\epsilon_2}\|u\|^2_{_{2,\Omega}}\right),
\end{equation}
for every $\epsilon_2>0$, and for some constant $C_{\epsilon^2_2}>0$. Now, if $r_3>N/2$ and $s>d(d+2-N)^{-1}$, it follows that the maps
$\mathcal{W}_2(\Omega;\Gamma)\hookrightarrow L^{^{\frac{2r_3}{r_3-1}}}(\Omega)$ and $\mathcal{W}_2(\Omega;\Gamma)\hookrightarrow L^{^{\frac{2s}{s-1}}}_{\mu}(\Gamma)$
are both compact. Consequently, continuing as in the above procedures, we find that
\begin{equation}\label{cc12}
\left|\displaystyle\int_{\Omega}\lambda u^2\,dx\right|\,\leq\,\|\lambda\|_{_{r_3,\Omega}}\|u\|^2_{_{\frac{2r_3}{r_3-1},\Omega}}\,
\leq\,\|\lambda\|_{_{r_3,\Omega}}\left(\epsilon_3\|\nabla u\|^2_{_{2,\Omega}}+C_{\epsilon_3}\|u\|^2_{_{2,\Omega}}\right)\,
\leq\,\|\lambda\|_{_{r_3,\Omega}}\left(\epsilon_3\|u\|^2_{_{\mathcal{W}_2(\Omega;\Gamma)}}+C_{\epsilon_3}\|u\|^2_{_{2,\Omega}}\right),
\end{equation}
and
\begin{equation}\label{cc13}
\left|\displaystyle\int_{\Gamma}\beta u^2\,d\mu\right|\,\leq\,\|\beta\|_{_{s,\Gamma}}\|u\|^2_{_{\frac{2s}{s-1},\Gamma}}\,
\leq\,\|\beta\|_{_{s,\Gamma}}\left(\epsilon_4\|\nabla u\|^2_{_{2,\Omega}}+C_{\epsilon_4}\|u\|^2_{_{2,\Omega}}\right)\,
\leq\,\|\beta\|_{_{s,\Gamma}}\left(\epsilon_4\|u\|^2_{_{\mathcal{W}_2(\Omega;\Gamma)}}+C_{\epsilon_4}\|u\|^2_{_{2,\Omega}}\right),
\end{equation}
and
\begin{equation}\label{cc14}
\gamma_0\displaystyle\int_{\Gamma}u^2\,d\mu\,\leq\,|\gamma_0|\left(\epsilon_5\|u\|^2_{_{\mathcal{W}_2(\Omega;\Gamma)}}+C_{\epsilon_5}\|u\|^2_{_{2,\Omega}}\right),
\end{equation}
for all $\epsilon_3,\,\epsilon_4,\epsilon_5>0$, and for some positive constants $C_{\epsilon_3},\,C_{\epsilon_4},\,C_{\epsilon_5}$. Then, if $\gamma_0\neq0$, we select
$$\epsilon_1:=\frac{\min\{c_0,c^{\star}_0\}}{20\|\hat{\mathfrak{a}}\|_{_{r_1,\Omega}}},\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,
\epsilon_2:=\frac{\min\{c_0,c^{\star}_0\}}{20\|\check{\mathfrak{a}}\|_{_{r_2,\Omega}}},$$
$$\epsilon_3:=\frac{\min\{c_0,c^{\star}_0\}}{10\|\lambda\|_{_{r_3,\Omega}}},\,\,\,\,\,\,\,\,\epsilon_4:=\frac{\min\{c_0,c^{\star}_0\}}{10\|\beta\|_{_{s,\Gamma}}},
\,\,\,\,\,\,\,\,\epsilon_5:=\frac{\min\{c_0,c^{\star}_0\}}{10|\gamma_0|},$$
and put
\begin{equation}\label{delta-star}
\delta^{\star}_0:=c_0+\frac{20\left(C_{\epsilon^2_1}\|\hat{\mathfrak{a}}\|^2_{_{r_1,\Omega}}+
C_{\epsilon^2_2}\|\check{\mathfrak{a}}\|^2_{_{r_2,\Omega}}\right)}{\min\{c_0,c^{\star}_0\}}+C_{\epsilon_3}\|\lambda\|_{_{r_3,\Omega}}+
C_{\epsilon_4}\|\beta\|_{_{s,\Gamma}}+C_{\epsilon_5}|\gamma_0|.
\end{equation}
Then, by combining the inequalities
(\ref{cc09}), (\ref{cc10}), (\ref{cc11}), (\ref{cc12}), (\ref{cc13}), (\ref{cc14}) together with the selections of $\epsilon_i>0$ ($1\leq i\leq5$),
we arrive at the key inequality\\
\begin{equation}
\label{3.1.06}
\frac{\min\{c_0,c^{\star}_0\}}{2}\|u\|^2_{_{\mathcal{W}_2(\Omega;\Gamma)}}\,\leq\,\mathcal{E}_{\mu}(u,u)+\delta^{\star}_0\|u\|^2_{_{2,\Omega}},
\,\,\,\,\,\,\,\textrm{for all}\,\,u\in\mathcal{W}_2(\Omega;\Gamma).
\end{equation}
\indent\\
Inequality (\ref{3.1.06}) shows that the form $\mathcal{E}_{\mu}(\cdot,\cdot)$ is weakly coercive, as asserted.
To complete the proof, let $(f,g)\in\mathbb{X\!}^{\,p,q}(\Omega;\Gamma)$, for $p\geq(2^{\ast}_{_N})'$ and $q\geq(2^{\ast}_{_d})'$, where
$2^{\ast}_{_N},\,2^{\ast}_{_d}$ are given as in (\ref{linear-critical-exp}) (and $r'$ denotes the conjugate of $r\in(1,\infty)$).
Then, using (\ref{2.03}) and (\ref{2.04}),
it follows that the functional $T_{\mu}:\mathcal{W}_2(\Omega;\Gamma)
\rightarrow\mathbb{R\!}$\,, given by $$T_{\mu}v:=\displaystyle\int_{\Omega}fv\,dx+\displaystyle\int_{\Gamma}gv\,d\mu$$
is linear and continuous. Therefore, an application of Lax-Milgram theorem theorem gives the existence of an unique function
$u\in\mathcal{W}_2(\Omega;\Gamma)$ fulfilling (\ref{cc00}), as desired.

\label{weak-sol}
A function $u\in\mathcal{W}_2(\Omega;\Gamma)$ is said to be a \textbf{weak solution of (\ref{1.05})}, if
\begin{equation}
\label{3.1.07}\mathcal{E}_{\mu}(u,\varphi)=\displaystyle\int_{\Omega}f\varphi\,dx+
\displaystyle\int_{\Gamma}g\varphi\,d\mu\,,\indent\,\,\textrm{for all}\,\,\varphi\in\mathcal{W}_2(\Omega;\Gamma).
\end{equation}
Also, $u\in\mathcal{W}_2(\Omega;\Gamma)$ is called a \textbf{weak subsolution of (\ref{1.05})}, if
\begin{equation}
\label{3.1.08}\mathcal{E}_{\mu}(u,\varphi)\,\leq\,\displaystyle\int_{\Omega}f\varphi\,dx+
\displaystyle\int_{\Gamma}g\varphi\,d\mu\,\,\,\textrm{for all}\,\,\varphi\in\mathcal{W}_2(\Omega;\Gamma)^+
:=\{w\in\mathcal{W}_2(\Omega;\Gamma)\mid w\geq0\},
\end{equation}
and if the reverse inequality of (\ref{3.1.08}) holds, then
$u\in\mathcal{W}_2(\Omega;\Gamma)$ is called a \textbf{weak supersolution of (\ref{1.05})}.\\

\label{Lem0}
Let $u\in\mathcal{W}_2(\Omega;\Gamma)$, and assume that $u_k|_{_{\Gamma}}\in D(\Lambda_{_{\Gamma}})$. Given $m_1,\,m_2\geq1$ integers and
$\xi\in\{1,\ldots,m_1\}$, and $\zeta\in\{1,\ldots,m_2\}$, let $s_{1,\xi}\in[2,2N(N-2)^{-1}]$ and $s_{2,\zeta}\in[2,2d(N-2)^{-1}]$.
Assume that there exists constants $\hat{k}_0,\,\gamma_0\geq0$, and positive constants $\theta_{1,\xi},\,\theta_{2,\zeta}$, such that
for all  $k\geq\hat{k}_0$, we have
\begin{equation}\label{Lem0-02}
\|u_k\|^2_{_{\mathcal{W}_2(\overline{\Omega})}}\,\leq\,\gamma_0\left(\|u_k\|^2_{_{2,\Omega_k}}
+k^2\displaystyle\sum^{m_1}_{\xi=1}|\Omega_k|
^{^{\frac{2(1+\theta_{1,\xi})}{s_{1,\xi}}}}+k^2\displaystyle\sum^{m_2}_{\zeta=1}\mu(\Gamma_k)^{^{\frac{2(1+\theta_{2,\zeta})}{s_{2,\zeta}}}}\right).
\end{equation}
Then there exists a constant $C^{\ast}_0>0$ (independent of $u$ and $\hat{k}_0$) such that
\begin{equation}\label{Lem0-03}
\textrm{ess}\displaystyle\sup_{\overline{\Omega}}[u]
\,\leq\,C^{\ast}_0\left(\|u\|^2_{_{2,\Omega}}+\hat{k}^2_0\right)^{1/2}.
\end{equation}

Given $\hat{k}\geq\hat{k}_0$ fixed, without loss of generality, we prove the result for
$$\theta_{1,\xi}=\theta_{2,\zeta}=\theta:=\min\left\{\min\{\theta_{1,\xi}\mid1\leq\xi\leq m_1\}\cup\min\{\theta_{2,\zeta}\mid1\leq\zeta\leq m_2\}\right\}$$
for each $\xi\in\{1,\ldots,m_1\}$ and $\zeta\in\{1,\ldots,m_2\}$. Then,
define the sequences $\{k_n\}_{n\geq0}$,\, $\{y_n\}_{n\geq0}$,\, $\{z_n\}_{n\geq0}$ of positive real numbers, by:
\begin{equation}\label{Lem0-06}
k_n:=(2-2^{-n})\hat{k},\,\,\,\,\,\,\,\,\,\,\,\,\,y_n:=\hat{k}^{-2}\|u_{k_n}\|^2_{_{2,\Omega_k}},
\end{equation}
and
\begin{equation}\label{Lem0-07}
z_n:=\displaystyle\sum^{m_1}_{\xi=1}|\Omega_{k_n}|^{^{\frac{2}{s_{1,\xi}}}}
+\displaystyle\sum^{m_2}_{\zeta=1}\mu(\Gamma_{k_n})^{^{\frac{2}{s_{2,\zeta}}}}.
\end{equation}
Clearly $k_n\geq\hat{k}\geq\hat{k}_0$ for each nonnegative integer $n$. Taking into account
the definitions of the sequences defined above together with H\"older's inequality and (\ref{2.03}), we calculate and get that\\[2ex]
$\hat{k}^2y_{n+1}\,\leq\,|\Omega_{k_{n+1}}|^{2/N}\left\|u_{k_{n+1}}\right\|^2_{_{2^{\ast}_{_N},\Omega}}$\\
\begin{equation}\label{Lem0-08}
\indent\indent\leq\,
c\left\{(k_{n+1}-k_n)^{-2}\hat{k}^2y_n\right\}^{2/N}\|u_{k_{n+1}}\|^2_{_{\mathcal{W}_2(\overline{\Omega})}}
\,\leq\,c\,4^{n+1}y_n^{2/N}\|u_{k_{n+1}}\|^2_{_{\mathcal{W}_2(\overline{\Omega})}},\,\,\,\,\,\,\,\,\,\,\,\,
\end{equation}
where $c>0$ is a constant that varies from line to line (this will be assumed for the remaining of the proof). Similarly, one has
\begin{equation}\label{Lem0-09}
4^{-(n+1)}\hat{k}^2z_{n+1}\,\leq\,(k_{n+1}-k_n)^2z_{n+1}\,\leq\,c\|u_{k_{n}}\|^2_{_{\mathcal{W}_2(\overline{\Omega})}}.
\end{equation}
Applying assumption (\ref{Lem1-02}) yields that
\begin{equation}\label{Lem0-10}
\|u_{k_{n+1}}\|^2_{_{\mathcal{W}_2(\overline{\Omega})}}\,\leq\,\gamma_02^{n+4}\hat{k}^2(y_n+z^{1+\theta}_n),
\end{equation}
and then combining (\ref{Lem0-08}), (\ref{Lem0-09}), and (\ref{Lem0-10}), we arrive at
\begin{equation}\label{Lem0-11}
y_{n+1}\,\leq\,c'\,8^n(y^{1+\delta}_n+z^{1+\theta}_ny^{\delta}_n)\,\,\textrm{and}\,\,
z_{n+1}\,\leq\,c'\,8^n(y_n+z^{1+\theta}_n),\,\,\textrm{for each integer}\,\,n\geq0,
\end{equation}
for some constant $c'>0$, where $\delta:=2/N$. Now, it is clear that
\begin{equation}\label{Lem0-12}
y_0\,\leq\,\hat{k}^{-2}\|u\|^2_{_{2,\Omega_k}}.
\end{equation}
On the other hand, using (\ref{Lem0-02}) and proceeding as above, we find that
$$(\hat{k}-\hat{k}_0)^2z_0\,\leq\,c\gamma_0\left(\|u_{k_0}\|^2_{_{2,\Omega_k}}+k^2_0\displaystyle\sum^{m_1}_{\xi=1}|\Omega|^{^{\frac{2(1+\theta)}{s_{1,\xi}}}}
+k^2_0\displaystyle\sum^{m_2}_{\zeta=1}\mu(\Gamma)^{^{\frac{2(1+\theta)}{s_{2,\zeta}}}}\right).$$
Thus setting
$$c'':=c\gamma_0\max\left\{1,\,\displaystyle\sum^{m_1}_{\xi=1}|\Omega|^{^{\frac{2(1+\theta)}{s_{1,\xi}}}}
+\displaystyle\sum^{m_2}_{\zeta=1}\mu(\Gamma)^{^{\frac{2(1+\theta)}{s_{2,\zeta}}}}\right\},$$
we obtain that
\begin{equation}\label{Lem0-13}
z_0\,\leq\,\displaystyle\frac{c''}{(\hat{k}-\hat{k}_0)^2}\left(\|u_{k_0}\|^2_{_{2,\Omega_{k_0}}}+k^2_0\right),
\,\,\,\,\,\,\,\,\,\,\,\,\textrm{for all}\,\,\,\hat{k}\geq k_0.
\end{equation}
Selecting $$d:=\min\left\{\delta,\,\frac{\theta}{1+\theta}\right\}\,\,\,\,\,\textrm{and}\,\,\,\,\,
\eta:=\min\left\{\frac{1}{(2c')^{^{\frac{1}{\delta}}}8^{^{\frac{1}{\delta d}}}},\,\frac{1}{(2c')^{^{\frac{1+\theta}{\theta}}}\,8^{^{\frac{1}{\theta d}}}}\right\},$$
and choosing
\begin{equation}\label{Lem0-14}
\hat{k}:=\max\left\{\displaystyle\frac{1}{\sqrt{\eta}}\|u\|_{_{2,\Omega}},\,
\displaystyle\frac{\sqrt{c''}}{\eta^{^{\frac{1}{2(1+\theta)}}}}
\left(\|u\|^2_{_{2,\Omega}}+\hat{k}^2_0\right)^{1/2}+\hat{k}_0\right\},
\end{equation}
we see that
\begin{equation}\label{Lem0-15}
\hat{k}\,\leq\,c^{\star}\left(\|u\|^2_{_{2,\Omega}}+\hat{k}^2_0\right)^{1/2}
\end{equation}
for some constant $c^{\star}>0$, and moreover the selection implies that
\begin{equation}\label{Lem0-16}
y_0\,\leq\,\eta\,\,\,\,\,\,\,\,\textrm{and}\,\,\,\,\,\,\,\,z_0\,\leq\,\eta^{^{\frac{1}{1+\theta}}}.
\end{equation}
Therefore, the sequences $\{y_n\}$,\, $\{z_n\}$ satisfy the conditions of Lemma \ref{lemma2}.
Thus, applying Lemma \ref{lemma2} for $\hat{k}$ given by (\ref{Lem0-14})
shows that $\displaystyle\lim_{n\rightarrow\infty}z_n=0$, and consequently
\begin{equation}\label{Lem0-17}
u(t)\,\leq\,\displaystyle\lim_{n\rightarrow\infty}k_n=2\hat{k}\,\,\,\,\,\,\,\,\textrm{a.e. in}\,\,\overline{\Omega}.
\end{equation}
Combining (\ref{Lem0-17}) with (\ref{Lem0-15}), we obtain (\ref{Lem0-03}), as desired.

\label{elliptic-bounded}
Assume all the conditions in Assumption \ref{As1}, let $(f,g)\in\mathbb{X\!}^{\,p,q}(\Omega;\Gamma)$, where $p\geq(2^{\ast}_{_N})'$ and $q\geq(2^{\ast}_{_d})'$, and assume that {\bf (A1)}, {\bf (A3)},
{\bf (B1)}, {\bf (B2)}, and {\bf (B4)} hold. If $u\in\mathcal{W}_2(\Omega;\Gamma)$ is a weak solution of (\ref{1.05}), then there exists a constant
$c^{\ast}=c(p,q,N,d,|\Omega|,\mu(\Gamma))>0$ such that
\begin{equation}\label{3.2.06}
|\|\mathbf{u}\||_{_{m_1(p,q),m_2(q,q)}}\,\leq\,c^{\ast}\left(|\|(f,g)\||_{_{p,q}}+\|u\|_{_{2,\Omega}}\right),
\end{equation}
where
\begin{equation}\label{m1}
m_1(p,q):=\left\{\begin{array}{lcl}
\frac{N}{N-2}\min\left\{\frac{p(N-2)}{N-2p},\,\frac{q(N-2)}{Nq-2q-dq+d}\right\},\,\,\textrm{if}\,\,p<N/2\,\,\textrm{and}\,\,q<\frac{d}{d+2-N},\\[1ex]
\frac{Np}{Np-2p-dp+d},\,\,\textrm{if}\,\,p<N/2<\frac{d}{d+2-N}\geq q,\,\,
\textrm{or}\,\,q<\frac{d}{d+2-N}\,\,\textrm{and}\,\,N/p\leq p<q;\\[1ex]
\frac{Nq}{Nq-2q-dq+d},\,\,\textrm{if}\,\,q<\frac{d}{d+2-N}\,\,\textrm{and}\,\,p\geq\max\{N/2,q\},\\[1ex]
r\in(2^{\ast}_{_N},\infty),\,\,\textrm{if}\,\,p=N/2\,\,\textrm{and}\,\,q\geq\frac{d}{d+2-N},\,\,\textrm{or}
\,\,q=\frac{d}{d+2-N}\,\,\textrm{and}\,\,p\geq N/2,\\[1ex]
\,\,\,\,\,\infty,\,\,\textrm{if}\,\,p>N/2\,\,\,\textrm{and}\,\,\,q>\frac{d}{d+2-N},
\end{array}
\right.
\end{equation}
and
\begin{equation}\label{m2}
m_2(p,q):=\left\{\begin{array}{lcl}
\frac{d}{N-2}\min\left\{\frac{p(N-2)}{N-2p},\,\frac{q(N-2)}{Nq-2q-dq+d}\right\},\,\,\textrm{if}\,\,p<N/2\,\,\textrm{and}\,\,q<\frac{d}{d+2-N},\\[1ex]
\frac{dp}{Np-2p-dp+d},\,\,\textrm{if}\,\,p<N/2<\frac{d}{d+2-N}\geq q,\,\,
\textrm{or}\,\,q<\frac{d}{d+2-N}\,\,\textrm{and}\,\,N/p\leq p<q;\\[1ex]
\frac{dq}{Nq-2q-dq+d},\,\,\textrm{if}\,\,q<\frac{d}{d+2-N}\,\,\textrm{and}\,\,p\geq\max\{N/2,q\},\\[1ex]
s\in(2^{\ast}_{_d},\infty),\,\,\textrm{if}\,\,p=N/2\,\,\textrm{and}\,\,q\geq\frac{d}{d+2-N},\,\,\textrm{or}
\,\,q=\frac{d}{d+2-N}\,\,\textrm{and}\,\,p\geq N/2,\\[1ex]
\,\,\,\,\,\infty,\,\,\textrm{if}\,\,p>N/2\,\,\,\textrm{and}\,\,\,q>\frac{d}{d+2-N},
\end{array}
\right.
\end{equation}

Without loss of generality, we will only give the proof for the case when condition {\bf (C2)} holds. Also, for simplicity,
we assume that $N>2$ (the case $N=2$ possesses sharper embedding results; e.g. Theorem \ref{embeddings}).
First of all, it is easy to see that it is enough to show the estimate (\ref{3.2.06}) for $u$ subsolution of (\ref{1.05})
(cf. Definition \ref{weak-sol}). For a supersolution, the assertion will follow as well, since $-u$ will be a subsolution,
and hence it will be valid for solutions by combining the two inequalities. Let $u\in\mathcal{W}_2(\Omega;\Gamma)$ solve the inequality
\begin{equation}
\label{3.2.09}\mathcal{E}_{\mu}(u,\varphi)\,\leq\,\displaystyle\int_{\Omega}f\varphi\,dx+
\displaystyle\int_{\Gamma}g\varphi\,d\mu\,,\,\,\,\,\,\,\,\forall\,\varphi\in\mathcal{W}_2(\Omega;\Gamma)^+.
\end{equation}
Given $k\geq2$ and $m\geq1$, let $v_{_m},\,w_{_m}\in\mathcal{W}_2(\Omega;\Gamma)^+$ be the functions given by (\ref{3.2.02}).
Then, testing (\ref{3.2.09}) with the function $v_{_m}$, using (\ref{1.04}), and the fact that
$\gamma_k:=\frac{k^2}{4(k-1)}\geq 1$, proceeding as in the proof of Proposition \ref{cont-coercive-form},
we take the sum over all $i,\,j$, and then integrate both sides to obtain that\\[2ex]
$c_0\|\nabla w_{_m}\|^2_{_{2,\Omega}}\,$\\
\begin{equation}\label{k-1st-est}
\leq\,\gamma_k\,\mathcal{E}_{_{\Omega}}(u,v_{_m})+\frac{k}{2}\left(|\Omega|^{^{\frac{1}{N}-\frac{1}{r_1}}}\|\hat{\mathfrak{a}}
\|_{_{r_1,\Omega}}+|\Omega|^{^{\frac{1}{N}-\frac{1}{r_2}}}\|\check{\mathfrak{a}}\|_{_{r_2,\Omega}}\right)
\left(\|w_{_m}\|_{_{\frac{2r_1}{r_1-2},\Omega}}+\|w_{_m}\|_{_{\frac{2r_2}{r_2-2},\Omega}}\right)\|\nabla w_{_m}\|_{_{2,\Omega}}+\|\lambda\|_{_{r_3,\Omega}}\|w_{_m}\|^2_{_{\frac{2r_3}{r_3-1},\Omega}},
\end{equation}
where the form $\mathcal{E}_{_{\Omega}}(\cdot,\cdot)$ is given by (\ref{3.1.03}). By virtue of {\bf (B1)} and {\bf (B2)}, we also have
$$\|w_{_m}\|^2_{_{D(\Lambda_{_{\Gamma}})}}\leq \eta'_0\,k^2\left(\mathcal{E}_{_{\Gamma}}(u,v_{_m})+\gamma_0\|w_{_m}\|^2_{_{2,\Gamma}}\right)+
\|\beta\|_{_{s,\Gamma}}\|w_{_m}\|^2_{_{\frac{2s}{s-1},\Gamma}}$$
for some positive constant $\eta'_0$, and for a constant $\gamma_0\in\mathbb{R\!}\,$, where $\mathcal{E}_{_{\Gamma}}(\cdot,\cdot)$
is defined as in (\ref{3.1.04}). Now, taking into account Young's inequality $2\xi\zeta\leq\epsilon^{-1}\xi^2+\epsilon\zeta^2$
(valid for all $\xi,\,\zeta\geq0$ and $\epsilon>0$) together with Remark \ref{R-embedding}(d), we have that\\[2ex]
$\displaystyle\frac{k}{2}\left(|\Omega|^{^{\frac{1}{N}-\frac{1}{r_1}}}\|\hat{\mathfrak{a}}\|_{_{r_1,\Omega}}+|\Omega|^{^{\frac{1}{N}-\frac{1}{r_2}}}
\|\check{\mathfrak{a}}\|_{_{r_2,\Omega}}\right)\left(\|w_{_m}\|_{_{\frac{2r_1}{r_1-2},\Omega}}+\|w_{_m}\|_{_{\frac{2r_2}{r_2-2},\Omega}}\right)\|\nabla w_{_m}\|_{_{2,\Omega}}$\\
$$\leq\,\frac{\epsilon_1}{2}\|\nabla w_{_m}\|^2_{_{2,\Omega}}+\frac{k^2}{2\epsilon_1}\left(|\Omega|^{^{\frac{1}{N}-\frac{1}{r_1}}}\|\hat{\mathfrak{a}}\|_{_{r_1,\Omega}}+
|\Omega|^{^{\frac{1}{N}-\frac{1}{r_2}}}\|\check{\mathfrak{a}}\|_{_{r_2,\Omega}}\right)^2\left(\|w_{_m}\|_{_{\frac{2r_1}{r_1-2},\Omega}}+\|w_{_m}\|_{_{\frac{2r_2}{r_2-2},\Omega}}\right)^2
\indent\indent\indent\indent\indent$$
$$\leq\,\displaystyle\frac{\epsilon_1}{2}\|\nabla w_{_m}\|^2_{_{2,\Omega}}+
\frac{k^2}{2\epsilon_1}\left(|\Omega|^{^{\frac{1}{N}-\frac{1}{r_1}}}\|\hat{\mathfrak{a}}\|_{_{r_1,\Omega}}+
|\Omega|^{^{\frac{1}{N}-\frac{1}{r_2}}}\|\check{\mathfrak{a}}\|_{_{r_2,\Omega}}\right)^2\left(\epsilon_k\|\nabla w_{_m}\|^2_{_{2,\Omega}}+
\frac{C}{\epsilon_k}\|w_{_m}\|^2_{_{2,\Omega}}\right),$$ for all $\epsilon_1,\,\epsilon_k>0$, and for some constant $C>0$. Choosing
$$\epsilon_k:=\frac{\epsilon^2_1}{k^2\left(|\Omega|^{^{\frac{1}{N}-\frac{1}{r_1}}}\|\hat{\mathfrak{a}}\|_{_{r_1,\Omega}}+
|\Omega|^{^{\frac{1}{N}-\frac{1}{r_2}}}\|\check{\mathfrak{a}}\|_{_{r_2,\Omega}}\right)^2}$$ in the above calculation,
we obtain that\\[2ex]
$\displaystyle\frac{k}{2}\left(|\Omega|^{^{\frac{1}{N}-\frac{1}{r_1}}}\|\hat{\mathfrak{a}}\|_{_{r_1,\Omega}}+|\Omega|^{^{\frac{1}{N}-\frac{1}{r_2}}}
\|\check{\mathfrak{a}}\|_{_{r_2,\Omega}}\right)\left(\|w_{_m}\|_{_{\frac{2r_1}{r_1-2},\Omega}}+\|w_{_m}\|_{_{\frac{2r_2}{r_2-2},\Omega}}\right)\|\nabla w_{_m}\|_{_{2,\Omega}}$\\
\begin{equation}\label{k-2nd-est}
\leq\,\epsilon_1\|\nabla w_{_m}\|^2_{_{2,\Omega}}+\frac{k^4C}{2\epsilon^3_1}\left(|\Omega|^{^{\frac{1}{N}-\frac{1}{r_1}}}\|\hat{\mathfrak{a}}\|_{_{r_1,\Omega}}+
|\Omega|^{^{\frac{1}{N}-\frac{1}{r_2}}}\|\check{\mathfrak{a}}\|_{_{r_2,\Omega}}\right)^4\|w_{_m}\|^2_{_{2,\Omega}},
\end{equation}
for all $\epsilon_1>0$. In a similar way, recalling the compactness of the maps
$\mathcal{W}_2(\Omega;\Gamma)\hookrightarrow L^{^{\frac{2r_3}{r_3-1}}}(\Omega)$ and $\mathcal{W}_2(\Omega;\Gamma)\hookrightarrow L^{^{\frac{2s}{s-1}}}_{\mu}(\Gamma)$
together with Young's inequality and Remark \ref{R-embedding}(d), we get that
\begin{equation}\label{k-3rd-est}
\|\lambda\|_{_{r_3,\Omega}}\|w_{_m}\|^2_{_{\frac{2r_3}{r_3-1},\Omega}}\,\leq\,\epsilon_2\|\nabla w_{_m}\|^2_{_{2,\Omega}}+
C_{_{\frac{\epsilon_2}{\|\lambda\|_{_{r_3,\Omega}}}}}\|w_{_m}\|^2_{_{2,\Omega}},
\end{equation}
and
\begin{equation}\label{k-4th-est}
\|\beta\|_{_{s,\Omega}}\|w_{_m}\|^2_{_{\frac{2s}{s-1},\Gamma}}\,\leq\,\epsilon_3\|\nabla w_{_m}\|^2_{_{2,\Omega}}+
C'_{_{\frac{\epsilon_3}{\|\beta\|_{_{s,\Gamma}}}}}\|w_{_m}\|^2_{_{2,\Omega}},
\end{equation}
and
\begin{equation}\label{k-5th-est}
\gamma_0\|w_{_m}\|^2_{_{2,\Gamma}}\,\leq\,\epsilon_4\|\nabla w_{_m}\|^2_{_{2,\Omega}}+
C''_{_{\frac{\epsilon_4}{|\gamma_0|}}}\|w_{_m}\|^2_{_{2,\Omega}}\,\,\,\,\,\,\,\,\,\,\,\,\,\textrm{(if}\,\,\gamma_0\neq0\,\textrm{)},
\end{equation}
for every $\epsilon_2,\,\epsilon_3,\,\epsilon_4>0$, and for some positive constants
$C_{_{\frac{\epsilon_2}{\|\lambda\|_{_{r_3,\Omega}}}}}$, \,$C'_{_{\frac{\epsilon_3}{\|\beta\|_{_{s,\Gamma}}}}}$,\,
$C''_{_{\frac{\epsilon_4}{|\gamma_0|}}}$. Letting $\epsilon_j:=c_0/8$ for $j\in\{1,2,3,4\}$, we put
\begin{equation}\label{3.2.10}
\delta^{\ast}:=\frac{C}{c^3_0}\left(|\Omega|^{^{\frac{1}{N}-\frac{1}{r_1}}}\|\hat{\mathfrak{a}}\|_{_{r_1,\Omega}}+
|\Omega|^{^{\frac{1}{N}-\frac{1}{r_2}}}\|\check{\mathfrak{a}}\|_{_{r_2,\Omega}}\right)^4
+C_{_{\frac{c_0}{8\|\lambda\|_{_{r_3,\Omega}}}}}+C'_{_{\frac{c_0}{8\|\beta\|_{_{s,\Gamma}}}}}+C''_{_{\frac{c_0}{8|\gamma_0|}}},
\end{equation}
We are lead to the following calculation:\\[2ex]
$\min\{c_0,\,1\}\left(\|\nabla w_{_m}\|^2_{_{2,\Omega}}+\|w_{_m}\|^2_{_{D(\Lambda_{_{\Gamma}})}}\right)\,
\leq\,8\left(\gamma_k\,\mathcal{E}_{_{\Omega}}(u,v_{_m})+\eta'_0\,k^2\mathcal{E}_{_{\Gamma}}(u,v_{_m})
+k^4\delta^{\ast}\|w_{_m}\|^2_{_{2,\Omega}}\right)$\\
$$\indent\indent\indent\indent\indent\,\leq\,8k\left(\mathcal{E}_{_{\Omega}}(u,v_{_m})+2\eta'_0\,k\mathcal{E}_{_{\Gamma}}(u,v_{_m})
+2k^3\delta^{\ast}\|w_{_m}\|^2_{_{2,\Omega}}\right).$$\\
Taking the definition of $v_{_m}$ together with the assumption {\bf (A1)}, we combine the previous estimate to arrive at
\begin{equation}\label{3.2.11}
\|w_{_m}\|^2_{_{\mathcal{V}_2(\Omega;\Gamma)}}\,
\leq\,\frac{8\max\{\eta'_0,\,1\}}{\min\{c_0,\,1\}}k^4\left\{\mathcal{E}_{\mu}(u,v_{_m})+
\left(\delta^{\ast}+|\eta_0|+\min\{c_0,\,1\}(1+|\eta_0|)\right)\|w_{_m}\|^2_{_{2,\Omega}}\right\}.
\end{equation}
Letting $$\gamma^{\ast}:=\frac{8(c_1+c_2)\max\{\eta'_0,\,1\}\max\left\{1,\,\delta^{\ast}+|\eta_0|+\min\{c_0,\,1\}(1+|\eta_0|)\right\}}{\min\{c_0,\,1\}},$$\indent\\
and using the fact that $u\in\mathcal{W}_2(\Omega;\Gamma)$ fulfill (\ref{3.2.09}),
we get by means of (\ref{3.2.11}) together with (\ref{2.03}) and (\ref{2.04}), that
\begin{equation}\label{3.2.12}
\|w_{_m}\|^2_{_{\frac{2N}{N-2},\Omega}}+\|w_{_m}\|^2_{_{\frac{2d}{N-2},\Gamma}}\,\leq\,(c_1+c_2)\|w_{_m}\|^2_{_{\mathcal{V}_2(\Omega;\Gamma)}}
\,\leq\,k^4\gamma^{\ast}\left(\displaystyle\int_{\Omega}fv_{_m}\,dx+\displaystyle\int_{\Gamma}gv_{_m}\,d\mu+\|w_{_m}\|^2_{_{2,\Omega}}\right).
\end{equation}
As $v_{_m}\,\leq\,w^{^{2(k-1)/k}}_{_m}$ for each $k\geq2$, we see that
\begin{equation}
\label{3.2.13}\displaystyle\int_{\Omega}fv_{_m}\,dx\,\leq\,
\|f\|_{_{p,\Omega}}\|v_{_m}\|_{_{\frac{p}{p-1},\Omega}}\,\leq\,
\|f\|_{_{p,\Omega}}\|w_{_m}\|^{^{\frac{2(k-1)}{k}}}_{_{\left(\frac{p}{p-1}\right)\frac{2(k-1)}{k},\Omega}}
\end{equation}
and
\begin{equation}
\label{3.2.14}\displaystyle\int_{\Gamma}gv_{_m}\,d\mu\,\leq\,
\|g\|_{_{q,\Gamma}}\|v_{_m}\|_{_{\frac{q}{q-1},\Gamma}}\,\leq\,
\|g\|_{_{q,\Gamma}}\|w_{_m}\|^{^{\frac{2(k-1)}{k}}}_{_{\left(\frac{q}{q-1}\right)\frac{2(k-1)}{k},\Gamma}}.
\end{equation}\\
Furthermore, by a well known interpolation inequality (e.g. \cite{TAR07}, Lemma 8.2), we observe that
\begin{equation}\label{3.2.15}
\|w_{_m}\|^2_{_{2,\Omega}}\,\leq\,\|w_{_m}\|^{^{2(1-\theta)}}_{_{\frac{2N}{N-2},\Omega}}
\|w_{_m}\|^{^{2\theta}}_{_{\zeta,\Omega}}\,,
\end{equation}
where $\theta\in(0,1)$ is chosen such that $2^{-1}=\theta\zeta^{-1}+(1-\theta)(N-2)(2N)^{-1}$, and where
$\zeta:=4p(3p-2)^{-1}\,\leq\,2$. To estimate $\|w_{_m}\|^{^{2\theta}}_{_{\zeta,\Omega}}$, we use the fact that $w^{2/k}_{_m}\leq u^+$ together with
H\"older's inequality to deduce that
$$\|w_{_m}\|^2_{_{\zeta,\Omega}}=\left\|w^{^{\frac{2}{k}+\frac{2}{k}(k-1)}}_{_m}\right\|_{_{\frac{\zeta}{2},\Omega}}\,\leq\,
\|u^+\|_{_{2,\Omega}}\|w_{_m}\|^{^{\frac{2(k-1)}{k}}}_{_{\left(\frac{p}{p-1}\right)\frac{2(k-1)}{k},\Omega}}.$$
Inserting this estimate in (\ref{3.2.15}), we apply Young's inequality in (\ref{3.2.15} to achieve
\begin{equation}
\label{3.2.16}\|w_{_m}\|^2_{_{2,\Omega}}\,\leq\,c^{\ast}\,\|u^+\|_{_{2,\Omega}}
\|w_{_m}\|^{^{\frac{2(k-1)}{k}}}_{_{\left(\frac{p}{p-1}\right)\frac{2(k-1)}{k},\Omega}}+\epsilon\,\|w_{_m}\|^2_{_{\mathcal{W}_2(\Omega;\Gamma)}},
\end{equation}\\
for some constant $c^{\ast}>0$ and for all $\epsilon>0$. We now deal each of the cases (five in total), in accordance to the values of the
constants (\ref{m1}) and (\ref{m2}).\\[2ex]
$\bullet$\,\,\,{\it \underline{\textsc{Case 1:}} $p<N/2$ \,and\, $q<\frac{d}{d+2-N}$}.\\[2ex]
For this case, choose
\begin{equation}\label{Case1-01}
k=\vartheta_{p,q}:=\min\left\{\frac{p(N-2)}{N-2p},\,\frac{q(N-2)}{Nq-2q-dq+d}\right\}.
\end{equation}
Using this selection together with (\ref{2.03}) and (\ref{2.04}), from (\ref{3.2.13}), (\ref{3.2.14}), and (\ref{3.2.16}), we get that
\begin{equation}
\label{Case1-02}\displaystyle\int_{\Omega}fv_{_m}\,dx\,\leq\,
C\|f\|_{_{p,\Omega}}\|w_{_m}\|^{^{\frac{2(\vartheta_{p,q}-1)}{\vartheta_{p,q}}}}_{_{\frac{2N}{N-2},\Omega}}
\leq\,c^{^{\frac{2(\vartheta_{p,q}-1)}{\vartheta_{p,q}}}}_1C\|f\|_{_{p,\Omega}}
\|w_{_m}\|^{^{\frac{2(\vartheta_{p,q}-1)}{\vartheta_{p,q}}}}_{_{\mathcal{W}_2(\Omega;\Gamma)}},
\end{equation}
and
\begin{equation}
\label{Case1-03}\displaystyle\int_{\Gamma}gv_{_m}\,d\mu\,\leq\,
C'\|g\|_{_{q,\Gamma}}\|w_{_m}\|^{^{\frac{2(\vartheta_{p,q}-1)}{\vartheta_{p,q}}}}_{_{\frac{2d}{N-2},\Gamma}}
\leq\,c^{^{\frac{2(\vartheta_{p,q}-1)}{\vartheta_{p,q}}}}_2C'\|g\|_{_{q,\Gamma}}
\|w_{_m}\|^{^{\frac{2(\vartheta_{p,q}-1)}{\vartheta_{p,q}}}}_{_{\mathcal{W}_2(\Omega;\Gamma)}},
\end{equation}
and
\begin{equation}
\label{Case1-04}\|w_{_m}\|^2_{_{2,\Omega}}\,\leq\,c^{^{\frac{2(\vartheta_{p,q}-1)}{\vartheta_{p,q}}}}_1C''\|u^+\|_{_{2,\Omega}}
\|w_{_m}\|^{^{\frac{2(\vartheta_{p,q}-1)}{\vartheta_{p,q}}}}_{_{\mathcal{W}_2(\Omega;\Gamma)}}+\epsilon\,\|w_{_m}\|^2_{_{\mathcal{W}_2(\Omega;\Gamma)}},
\end{equation}
for some constants $C,\,C',\,C''>0$. Selecting $\epsilon>0$ appropriately, and combining (\ref{3.2.12}), (\ref{Case1-02}), (\ref{Case1-03}),
and (\ref{Case1-04}), we get the existence of a constant $C_0>0$, such that
$$\|w_{_m}\|^2_{_{\mathcal{W}_2(\Omega;\Gamma)}}\,\leq\,C_0\left(\|f\|_{_{p,\Omega}}+\|g\|_{_{q,\Gamma}}+\|u^+\|_{_{2,\Omega}}\right)
\|w_{_m}\|^{^{\frac{2(\vartheta_{p,q}-1)}{\vartheta_{p,q}}}}_{_{\mathcal{W}_2(\Omega;\Gamma)}},$$
from where we arrive at
\begin{equation}\label{Case1-05}
\left\|w^{^{\frac{2}{\vartheta_{p,q}}}}_{_m}\right\|_{_{\frac{N\vartheta_{p,q}}{N-2},\Omega}}+
\left\|w^{^{\frac{2}{\vartheta_{p,q}}}}_{_m}\right\|_{_{\frac{d\vartheta_{p,q}}{N-2},\Gamma}}
\,\leq\,C_0\left(\|f\|_{_{p,\Omega}}+\|g\|_{_{q,\Gamma}}+\|u^+\|_{_{2,\Omega}}\right).
\end{equation}
Since the sequence $w^{^{\frac{2}{\vartheta_{p,q}}}}_{_m}:=\left[\psi_{_{\frac{\vartheta_{p,q}}{2},m}}(u)\right]^{^{\frac{2}{\vartheta_{p,q}}}}$
(for the function $\psi_{_{t,m}}(\cdot)$ given by (\ref{3.2.01}))
is increasing with $w^{^{\frac{2}{\vartheta_{p,q}}}}_{_m}\stackrel{m\rightarrow\infty}{\longrightarrow}u^+$, and application of
the Monotone Convergence Theorem of Lebesgue in (\ref{Case1-05}) gives
\begin{equation}\label{Case1-06}
|\|\textbf{u}^+\||_{_{\frac{N\vartheta_{p,q}}{N-2},\frac{d\vartheta_{p,q}}{N-2}}}\,\leq\,C_0\left(|\|(f,g)\||_{_{p,q}}+\|u^+\|_{_{2,\Omega}}\right).
\end{equation}
This completes the proof of the first case of the theorem.\\[2ex]
$\bullet$\,\,\,{\it \underline{\textsc{Case 2:}} $p<N/2<\frac{d}{d+2-N}\geq q$, or\,
$q<\frac{d}{d+2-N}$\, and \,$N/p\leq p<q$}.\\[2ex]
For this case, we put
\begin{equation}\label{Case2-01}
k:=\varsigma_p:=\frac{p(N-2)}{Np-2p-dp+d}.
\end{equation}
Inserting this in (\ref{3.2.13}), (\ref{3.2.14}), and (\ref{3.2.16}), and using the fact that $N-2<d<N$ and $q'<p'$, we get that
$$\displaystyle\int_{\Omega}fv_{_m}\,dx
\,\leq\,\|f\|_{_{p,\Omega}}\|w_{_m}\|^{^{\frac{2(\varsigma_{p}-1)}{\varsigma_{p}}}}_{_{\frac{2d}{N-2},\Omega}}
\leq\,c^{^{\frac{2(\varsigma_{p}-1)}{\varsigma_{p}}}}_1C_1\|f\|_{_{p,\Omega}}
\|w_{_m}\|^{^{\frac{2(\varsigma_{p}-1)}{\varsigma_{p}}}}_{_{\mathcal{W}_2(\Omega;\Gamma)}},$$
and
$$\displaystyle\int_{\Gamma}gv_{_m}\,d\mu\,\leq\,\|g\|_{_{q,\Gamma}}
\|w_{_m}\|^{^{\frac{2(\varsigma_{p}-1)}{\varsigma_{p}}}}_{_{\left(\frac{q}{q-1}\right)\frac{2(\varsigma_p-1)}{\varsigma_p},\Gamma}}
\,\leq\,C'_1\|g\|_{_{q,\Gamma}}\|w_{_m}\|^{^{\frac{2(\varsigma_{p}-1)}{\varsigma_{p}}}}_{_{\frac{2d}{N-2},\Gamma}}
\leq\,c^{^{\frac{2(\varsigma_{p}-1)}{\varsigma_{p}}}}_2C''_1\|g\|_{_{q,\Gamma}}
\|w_{_m}\|^{^{\frac{2(\varsigma_{p}-1)}{\varsigma_{p}}}}_{_{\mathcal{W}_2(\Omega;\Gamma)}},$$
and
$$\|w_{_m}\|^2_{_{2,\Omega}}\,\leq\,c^{^{\frac{2(\varsigma_{p}-1)}{\varsigma_{p}}}}_1\|u^+\|_{_{2,\Omega}}
\|w_{_m}\|c^{^{\frac{2(\varsigma_{p}-1)}{\varsigma_{p}}}}_{_{\mathcal{W}_2(\Omega;\Gamma)}}+\epsilon\,\|w_{_m}\|^2_{_{\mathcal{W}_2(\Omega;\Gamma)}},$$
for some constants $C_1,\,C'_1,\,C''_1>0$. Proceeding in the exact way as the previous case, we have
\begin{equation}\label{Case2-02}
|\|\textbf{u}^+\||_{_{\frac{N\varsigma_{p}}{N-2},\frac{d\varsigma_{p}}{N-2}}}\,\leq\,C'_0\left(|\|(f,g)\||_{_{p,q}}+\|u^+\|_{_{2,\Omega}}\right)
\end{equation}
for some positive constant $C_0>0$, which is the desired conclusion for the second case.\\[2ex]
$\bullet$\,\,\,{\it \underline{\textsc{Case 3:}} $q<\frac{d}{d+2-N}$ \,and\, $p\geq\max\{N/2,q\}$}.\\[2ex]
Letting
\begin{equation}\label{Case3-01}
k:=\varsigma_q:=\frac{q(N-2)}{Nq-2q-dq+d},
\end{equation}
this case follows in the same way as in the previous case; we deduce the existence of a constant $C''_0>0$ such that
\begin{equation}\label{Case3-02}
|\|\textbf{u}^+\||_{_{\frac{N\varsigma_{q}}{N-2},\frac{d\varsigma_{q}}{N-2}}}\,\leq\,C''_0\left(|\|(f,g)\||_{_{p,q}}+\|u^+\|_{_{2,\Omega}}\right).
\end{equation}
$\bullet$\,\,\,{\it \underline{\textsc{Case 4:}} $p=N/2$\, and \,$q\geq\frac{d}{d+2-N}$, or
\,$q=\frac{d}{d+2-N}$\, and \,$p\geq N/2$}.\\[2ex]
We will prove the case when $p=N/2$\, and \,$q\geq\frac{d}{d+2-N}$; the other situation follows in an analogous manner.
Given $r>2^{\ast}_{_N}$, \,$s>2^{\ast}_{_d}$ arbitrarily fixed, put $\tau_{r,s}:=\max\{r,s,N\}$.
Then there exists $p_0\in[(2^{\ast}_{_N})',N/2)$ such that
$$f\in L^{p_0}(\Omega)\indent\indent\textrm{and}\indent\indent\frac{p_0}{N-2p_0}=\frac{\tau_{r,s}}{d}.$$
Given $r>2^{\ast}_{_N}$, \,$s>2^{\ast}_{_d}$ arbitrarily fixed, put $\tau_{r,s}:=\max\{r,s,N\}$.
In the same way, one can find $q_0\in[(2^{\ast}_{_d})',d(d+2-N)^{-1})$ such that
$$g\in L^{q_0}_{\mu}(\Gamma)\indent\indent\textrm{and}\indent\indent\frac{q_0}{Nq_0-2q_0-dq_0+d}=\frac{\tau_{r,s}}{d}.$$
Then, selecting $\vartheta_{p_0,q_0}$ as in (\ref{Case1-01}), and applying multiple times H\"older's inequality,
we end up getting the inequality
\begin{equation}\label{Case4-01}
|\|\textbf{u}^+\||_{_{r,s}}\,\leq\,C_2\left(|\|(f,g)\||_{_{p_0,q_0}}+\|u^+\|_{_{2,\Omega}}\right)
\,\leq\,C'_2\left(|\|(f,g)\||_{_{p,q}}+\|u^+\|_{_{2,\Omega}}\right),
\end{equation}
for some constants $C_2,\,C'_2>0$. This establishes the fourth case.\\[2ex]
$\bullet$\,\,\,{\it \underline{\textsc{Case 5:}} $p>N/2$\, and \,$q>\frac{d}{d+2-N}$}.\\[2ex]
For this part, a complete proof is given for the parabolic case in the proof of Theorem \ref{Thm-Partial-Bounded}, so we will only sketch the main
steps of this corresponding elliptic version.
Let $u\in\mathcal{W}_2(\Omega;\Gamma)$ be a weak solution of problem (\ref{1.05}), and
let $u_k$ be the function given by (\ref{u_k def}). Then we have
\begin{equation}\label{thm0-03}
\mathcal{E}_{\mu}(u,u_k)=\displaystyle\int_{\Omega_k}fu_k\,dx+\displaystyle\int_{\Gamma_k}gu_k\,d\mu,
\end{equation}
where we recall the definition of the form $\mathcal{E}_{\mu}(\cdot,\cdot)$ in (\ref{3.1.01}). Estimating the right hand side in (\ref{thm0-03}) and taking
into account Assumptions {\bf (A3)}, {\bf (B4)}, and (\ref{1.04}), we apply Young's inequality multiple times and use Remark \ref{R-embedding}(d)
to infer (after multiple calculations) that
\begin{equation}\label{thm0-10}
\mathcal{E}_{\mu}(u,u_k)\,\geq\,\displaystyle\frac{c_0}{4}\|\nabla u_k\|^2_{_{2,\Omega_k}}+
c^{\#}\|u_k\|^2_{_{D(\Lambda_{_{\Gamma}})}}-
\displaystyle\int_{\Omega_k}\mathfrak{h}(|u_k|^2+k^2)\,dx-\displaystyle\int_{\Gamma_k}\mathfrak{k}(|u_k|^2+k^2)\,d\mu,
\end{equation}
for some constant $c^{\#}>0$, where
$$\mathfrak{h}:=\frac{1}{c_0}\displaystyle\sum^N_{i=1}|\hat{a}_i|^2+M^{\star}+|\lambda|\in L^{^{\min\left\{\frac{r_1}{2},r_3\right\}}}(\Omega)^+$$
and $$\mathfrak{k}:=\min\{1,c^{\star}_1\}(|c^{\ast}_1|+2|\beta|)+c^{\star}_3|\rho|\in L^{^{\min\{s,\theta\}}}_{\mu}(\Gamma)^+,$$
for some constant $c^{\ast}_1>0$, and where
$$M^{\star}:=\max\left\{\|\hat{\mathfrak{a}}\|_{_{r_1,\Omega}},\|\check{\mathfrak{a}}\|_{_{r_2,\Omega}}\right\}
\left(C_1\|\hat{\mathfrak{a}}\|_{_{r_1,\Omega}}+C_2\|\check{\mathfrak{a}}\|_{_{r_2,\Omega}}\right)/c_0>0,$$
for some constants $C_1,\,C_2>0$. It is also easy to see that
\begin{equation}\label{thm0-09}
\displaystyle\int_{\Omega_k}fu_k\,dx+\displaystyle\int_{\Gamma_k}gu_k\,d\mu\,
\leq\,\displaystyle\frac{1}{k}\displaystyle\int_{\Omega_k}|f|(|u_k|^2+k^2)\,dx+
\displaystyle\frac{1}{k}\displaystyle\int_{\Gamma_k}|g|(|u_k|^2+k^2)\,d\mu.
\end{equation}
Substituting all this into (\ref{thm0-03}) and recalling the equivalence of the norms $\|\cdot\|_{_{\mathcal{W}_2(\Omega;\Gamma)}}$
and $\|\cdot\|_{_{\mathcal{W}_2(\overline{\Omega})}}$, we deduce that
\begin{equation}\label{thm0-12}
\min\left\{1,\displaystyle\frac{c_0}{4},c^{\#}\right\}\|u_k\|^2_{_{\mathcal{W}_2(\overline{\Omega})}}\,\leq\,c\|u_k\|^2_{_{2,\Omega_k}}+
c\left(\displaystyle\int_{\Omega_k}\left(\frac{1}{k}|f|+\mathfrak{h}\right)(|u_k|^2+k^2)\,dx
+\displaystyle\int_{\Gamma_k}\left(\frac{1}{k}|g|+\mathfrak{k}\right)(|u_k|^2+k^2)\,d\mu\right),
\end{equation}
for some constant $c>0$. We now estimate the last two terms in (\ref{thm0-12}). Put
\begin{equation}\label{thm0-13}
\hat{k}^2_0:=\|f\|^2_{_{p,\Omega}}+\|g\|^2_{_{q,\Gamma}},\,\,\,\,\,\textrm{and}\,\,\,\,\,k\geq\hat{k}_0,
\end{equation}
and apply H\"older's inequality together with Young's inequality and Remark \ref{R-embedding}(d) to deduce that
\begin{equation}\label{thm0-14}
\displaystyle\int_{\Omega_k}\frac{1}{k}|f||u_k|^2\,dx\,\leq\,\displaystyle\frac{1}{k}\|f\|_{_{p,\Omega}}\|u_k\|^2_{_{\frac{2p}{p-1},\Omega_k}}
\,\leq\,\displaystyle\frac{k_0}{k}\left(\epsilon_1\|\nabla u_k\|^2_{_{2,\Omega_k}}+C_{\epsilon_1}\|u_k\|^2_{_{2,\Omega_k}}\right)
\,\leq\,\epsilon_1\|u_k\|^2_{_{\mathcal{W}_2(\overline{\Omega})}}+C_{\epsilon_1}\|u_k\|^2_{_{2,\Omega_k}},
\end{equation}
for all $\epsilon_1>0$, and for some constant $C_{\epsilon_1}>0$. Also, since $\mathfrak{h}\in L^{^{\min\{r_1,r_3\}}}(\Omega)$ and
$$\mathfrak{r}:=2\min\{r_1/2,\,r_3\}\left(\min\{r_1/2,\,r_3\}-1\right)^{-1}<
2N(N-2)^{-1},$$ proceeding in the same way as in the derivation of (\ref{thm0-14}), we get that
\begin{equation}\label{thm0-16}
\displaystyle\int_{\Omega_k}\mathfrak{h}|u_k|^2\,dx
\,\leq\,\|\mathfrak{h}\|_{_{\min\left\{\frac{r_1}{2},r_3\right\},\Omega}}\left(\epsilon_2\| u_k\|^2_{_{\mathcal{W}_2(\overline{\Omega})}}+C_{\epsilon_2}\|u_k\|^2_{_{2,\Omega_k}}\right),
\end{equation}
for every $\epsilon_2>0$, and for some constant $C_{\epsilon_2}>0$. Moreover, using the fact that $\mathfrak{k}\in L^{^{\min\{s,\theta\}}}_{\mu}(\Gamma)$ with
$$\mathfrak{s}:=2\min\{s,\theta\}\left(\min\{s,\theta\}-1\right)^{-1}<2d(N-2)^{-1},$$ we proceed in the exact way as above to deduce that
\begin{equation}\label{thm0-17}
\displaystyle\int_{\Gamma_k}\frac{1}{k}|g||u_k|^2\,d\mu
\,\leq\,\epsilon_3\|u_k\|^2_{_{\mathcal{W}_2(\overline{\Omega})}}+C_{\epsilon_3}\|u_k\|^2_{_{2,\Omega_k}},
\end{equation}
for all $\epsilon_3>0$, and for some constant $C_{\epsilon_3}>0$, and
\begin{equation}\label{thm0-18}
\displaystyle\int_{\Gamma_k}\mathfrak{k}|u_k|^2\,d\mu
\,\leq\,\|\mathfrak{k}\|_{_{\min\{s,\theta\},\Gamma}}\left(\epsilon_4\|u_k\|^2_{_{\mathcal{W}_2(\overline{\Omega})}}+C_{\epsilon_4}\|u_k\|^2_{_{2,\Omega_k}}\right),
\end{equation}
for every $\epsilon_4>0$, and for some constant $C_{\epsilon_4}>0$. Choosing
$$\epsilon_1=\epsilon_3=\frac{1}{8}\min\left\{1,\displaystyle\frac{c_0}{4},c^{\#}\right\},\,\,\,\,\,\,\,\,\,\,
\epsilon_2=\frac{1}{8\|\mathfrak{h}\|_{_{\min\left\{\frac{r_1}{2},r_3\right\},\Omega}}}\min\left\{1,\displaystyle\frac{c_0}{4},c^{\#}\right\},
\,\,\,\,\,\,\,\,\,\,\epsilon_4=\frac{1}{8\|\mathfrak{k}\|_{_{\min\{s,\theta\},\Gamma}}}\min\left\{1,\displaystyle\frac{c_0}{4},c^{\#}\right\},$$
we insert (\ref{thm0-14}), (\ref{thm0-16}), (\ref{thm0-17}), and (\ref{thm0-18}) into (\ref{thm0-12}), to arrive at
\begin{equation}\label{thm0-19}
\|u_k\|^2_{_{\mathcal{W}_2(\overline{\Omega})}}\,\leq\,\displaystyle\frac{2c}{\min\{1,c_0/4,c^{\#}\}}\left\{
C^{\star}_0\|u_k(t)\|^2_{_{2,\Omega_k}}\right.+
\left.k^2\displaystyle\int_{\Omega_k}\left(\frac{1}{k}|f|+\mathfrak{h}\right)\,dx\,+\,
k^2\displaystyle\int_{\Gamma_k}\left(\frac{1}{k}|g|+\mathfrak{k}\right)\,d\mu\right\},
\end{equation}
where
$$C^{\star}_0:=1+C_{\epsilon_1}+C_{\epsilon_2}\|\mathfrak{h}\|_{_{\min\{r_1,r_3\},\Omega}}
+C_{\epsilon_3}+C_{\epsilon_4}\|\mathfrak{k}\|_{_{\min\{s,\theta\},\Gamma}}.$$
Having this, we now produce estimates in the last two integral terms in (\ref{thm0-19}). In fact,
recalling that $k\geq k_0$ and applying H\"older's inequality, we see that
\begin{equation}\label{thm0-20}
\int_{\Omega_k}\frac{1}{k}|f|\,dx\,\leq\,|\Omega_k|^{^{1-\frac{1}{p}}},\,\,\,\,\,\displaystyle\int_{\Omega_k}\mathfrak{h}\,dx
\,\leq\,\|\mathfrak{h}\|_{_{\min\left\{\frac{r_1}{2},r_3\right\},\Omega}}|\Omega_k|^{2/\mathfrak{r}},
\end{equation}
and
\begin{equation}\label{thm0-22}
\displaystyle\int_{\Gamma_k}\frac{1}{k}|g|\,d\mu\,\leq\,\mu(\Gamma_k)^{^{1-\frac{1}{q}}},\,\,\,\,\,
\int_{\Gamma_k}\mathfrak{k}\,d\mu\,dt\,\leq\,\|\mathfrak{k}\|_{_{\min\{s,\theta\},\Gamma}}
\mu(\Gamma_k)^{2/\mathfrak{s}}dt.
\end{equation}
Put $$\gamma_0:=\displaystyle\frac{2c\max\left\{1,C^{\star}_0,\|\mathfrak{h}\|_{_{\min\left\{\frac{r_1}{2},r_3\right\},\Omega}},
\|\mathfrak{k}\|_{_{\min\{s,\theta\},\Gamma}}\right\}}{\min\{1,c_0/4,c^{\#}\}},$$
and we choose
$$\theta_{1,1}:=\frac{2p-N}{(N-2)p},\,\,\,\,\,\,\,
\theta_{1,2}:=\frac{2N+2\mathfrak{r}-N\mathfrak{r}}{(N-2)\mathfrak{r}},\,\,\,\,\,\,\,s_{1,1}=s_{1,2}:=2^{\ast}_{_N},$$
and
$$\theta_{2,1}:=\frac{dq+2q-Nq-d}{(N-2)q},\,\,\,\,\,\,\,
\theta_{2,2}:=\frac{2d+2\mathfrak{s}-N\mathfrak{s}}{(N-2)\mathfrak{s}},\,\,\,\,\,\,\,s_{2,1}=s_{2,2}:=2^{\ast}_{_d}.$$
Recalling the assumptions, one clearly sees that the parameters $\theta_{1,\xi},\,\theta_{2,\zeta}$ are all positive.
Using this, we substitute (\ref{thm0-20}), and (\ref{thm0-22}) into (\ref{thm0-19}), to arrive at
\begin{equation}\label{thm0-25}
\|u_k\|^2_{_{\mathcal{W}_2(\overline{\Omega})}}\,\leq\,\gamma_0\left(\|u_k\|^2_{_{2,\Omega_k}}
+k^2\displaystyle\sum^{2}_{\xi=1}|\Omega_k|
^{^{\frac{2(1+\theta_{1,\xi})}{s_{1,\xi}}}}+k^2\displaystyle\sum^{2}_{\zeta=1}\mu(\Gamma_k)^{^{\frac{2(1+\theta_{2,\zeta})}{s_{2,\zeta}}}}\right).
\end{equation}
Therefore, all the conditions of Lemma \ref{Lem1} are fulfilled, and thus
applying Lemma \ref{Lem1} to both $u$ and $-u$ (the latter one being a weak solution of (\ref{1.05}) for $f,\,g$ replaced by
$-f,\,-g$, respectively) gives the desired $L^{\infty}$-bound, completing the proof of the theorem.

\label{coercivity}
We consider the situation when the form $\mathcal{E}_{\mu}(\cdot,\cdot)$ is coercive. In this case the right hand bound in (\ref{3.2.06}) becomes independent on $u$, as we show below.
\begin{enumerate}
\item[(a)]\,\,\,Let $\xi\in\mathbb{R\!}$\,, and assume that
the measurable coefficient $\lambda(x)$ in the differential operator $\mathcal{A}$ in (\ref{1.01}) is of the form
$\lambda(x):=\upsilon(x)+\xi$, where $\upsilon\in L^{r_3}(\Omega)$ ($r_3>N/2$) and $\xi>\delta^{\star}_0$, for
$\delta^{\star}_0>0$ denotes the constant given by (\ref{delta-star}) for $\lambda$ replaced by $\upsilon$ (in (\ref{delta-star})). Then one can deduce that the
bilinear form $\mathcal{E}_{\mu}$ is coercive, and consequently, by virtue of Theorem \ref{elliptic-bounded}, if $u \in \mathcal{W}_2(\Omega;\Gamma)$ solves (\ref{1.05}), we have that\\
\begin{equation}\label{coercive-infinity}
|\|\mathbf{u}\||_{_{m_1(p,q),m_2(p,q)}}\,\leq\,c\,|\|(f,g)\||_{_{p,q}},
\end{equation}
\indent\\
for some constant $c>0$, where the constants $m_1(p,q),\,m_2(p,q)$ are given by (\ref{m1}) and (\ref{m2}),
respectively. To see this, observe that if
$u \in \mathcal{W}_2(\Omega;\Gamma)$ solves (\ref{3.1.07}), then $u$ is a weak solution of the boundary value problem
\begin{equation}
\label{ENBVP2}\left\{
\begin{array}{lcl}
\mathcal{A}u\,=\,f-\xi u\,\,\,\,\,\,\,\,\,\,\textrm{in}\,\,\Omega\\
\mathcal{B}u\,=\,\,\,\,\,g\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\textrm{on}\,\,\Gamma\\
\end{array}
\right.
\end{equation}
where the differential operators $\mathcal{A}$ and $\mathcal{B}$ are given in (\ref{1.01}) and (\ref{1.02}),
respectively. Hence, following the proof of Proposition \ref{cont-coercive-form}, we notice that\\[2ex]
$\|u\|^2_{_{\mathcal{W}_2(\Omega;\Gamma)}}\,\leq\,\displaystyle\frac{2}{\min\{c_0,c^{\star}_0\}}
\left(\mathcal{E}_{\mu}(u,u)+\delta^{\star}_0\|u\|^2_{_{2,\Omega}}\right)$\\
$$=\displaystyle\frac{2}{\min\{c_0,c^{\star}_0\}}\left(\displaystyle\int_{\Omega}fu\,dx+\displaystyle\int_{\Gamma}gu\,d\mu
-\left(\xi-\delta^{\star}_0)\right)\|u\|^2_{_{2,\Omega}}\right)\,
\leq\,\displaystyle\frac{2c'}{\min\{c_0,c^{\star}_0\}}|\|(f,g)\||_{_{p,q}}\|u\|_{_{\mathcal{W}_2(\Omega;\Gamma)}},$$
for some constant $c'>0$. This proves our claim.
\item[(b)]\,\,\,For bounded extension domains whose boundaries are upper $d$-sets (with respect to $\mu$),
for $d\in(N-2,N)$, one has that Remark \ref{R-embedding}(b)
holds. Then, consider now the case when $\beta(x)=\beta_0(x)+\zeta$, for $\beta_0\in L^{s}_{\mu}(\Gamma)$ ($s>d(d+2-N)^{-1}$)
and $\zeta>\delta^{\star}_0C_{\tau^{\ast}}$, where $\delta^{\star}_0>0$ is given by (\ref{delta-star}) (for $\beta_0$ instead of $\beta$), and for
$$\tau^{\ast}:=\frac{\min\{c_0,\,c^{\star}_0\}}{4\delta^{\star}_0}\,\,\,\,\,\,\,\,\textrm{and}\,\,\,\,\,\,\,\,
C_{\tau^{\ast}}>0\,\,\,\textrm{is a constant}.$$
Given $u\in \mathcal{W}_2(\Omega;\Gamma)$ a weak solution of (\ref{1.05}), $u$ solves the boundary value problem
\begin{equation}
\label{ENBVP2b}\left\{
\begin{array}{lcl}
\mathcal{A}u\,=\,\,\,\,\,f\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\textrm{in}\,\,\Omega\\
\mathcal{B}u\,=\,g-\zeta u\,\,\,\,\,\,\,\,\,\,\,\,\textrm{on}\,\,\Gamma\\
\end{array}
\right.
\end{equation}
Following as above together with the compactness of the embedding $\mathcal{W}_2(\Omega;\Gamma)\hookrightarrow L^2_{\mu}(\Gamma)$ and
Remark \ref{R-embedding}(d), we see that\\[2ex]
$\|u\|^2_{_{\mathcal{W}_2(\Omega;\Gamma)}}\,\leq\,\displaystyle\frac{2}{\min\{c_0,c^{\star}_0\}}
\left(\mathcal{E}_{\mu}(u,u)+\delta^{\star}_0\|u\|^2_{_{2,\Omega}}\right)$\\
$$\indent\indent\leq\,\displaystyle\frac{2}{\min\{c_0,c^{\star}_0\}}
\left(\mathcal{E}_{\mu}(u,u)+\delta^{\star}_0\left\{\tau^{\ast}
\|\nabla u\|_{_{2,\Omega}}+C_{\tau^{\ast}}\|u\|^2_{_{2,\Gamma}}\right\}\right).$$
Then, as in Case (a), using the above estimate, we get that
$$\|u\|^2_{_{\mathcal{W}_2(\Omega;\Gamma)}}\,\leq\,\displaystyle\frac{4}{\min\{c_0,c^{\star}_0\}}
\left(\displaystyle\int_{\Omega}fu\,dx+\displaystyle\int_{\Gamma}gu\,d\mu
-\left(\zeta-\delta^{\star}_0C_{\tau^{\ast}})\right)\|u\|^2_{_{2,\Gamma}}\right)\,
\leq\,\displaystyle\frac{4c''}{\min\{c_0,c^{\star}_0\}}|\|(f,g)\||_{_{p,q}}\|u\|_{_{\mathcal{W}_2(\Omega;\Gamma)}},$$\\
for some constant $c''>0$, and thus (\ref{coercive-infinity}) holds as well for this case.
\item[(c)]\,\,\,If $\xi\geq\delta^{\star}_0$ in part (a), or if $\zeta\geq\delta^{\star}_0C_{\tau^{\ast}}$ in part (b), then by replacing the space
$H^1(\Omega)$ by the space $H_0(\Omega)$ in the case condition {\bf (C1)} holds, then one gets the coercivity of the form
$\mathcal{E}_{\mu}(\cdot,\cdot)$, and in particular, this shows that under these conditions, problem (\ref{1.04}) possesses a unique
(modulo constant) weak solution $u\in H^1(\Omega)$. Same conclusion happens in the case when condition {\bf (C2)} is fulfilled, by replacing the
set $H^1_{\mu}(\Omega;\Gamma)$ by the closed subspace $H_{0,\mu}(\Omega;\Gamma)$.
\end{enumerate}

Let $u\in\mathcal{W}_2(\Omega;\Gamma)$ be a solution of (\ref{Diff-Ineq}), and assume that Remark \ref{coercivity}(a)
holds (the other case follows in a similar way). By {\bf (A2)} and {\bf (B3)} we have
$K(u^+,u^-)\leq0$, and $\Lambda_{_{\Gamma}}(u^+,u^-)\leq0$, and consequently $\mathcal{E}_{\mu}(u^+,u^-)\leq0$. Write
$$\mathfrak{C}^{\star}:=\left\{
\begin{array}{lcl}
\xi-\delta^{\star}_0,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\textrm{if Remark \ref{coercivity}(a) (or Remark \ref{coercivity}(c) related to (a)) holds};\\
\zeta-\delta^{\star}_0C_{\tau^{\ast}},\,\,\,\,\,\,\textrm{if Remark \ref{coercivity}(b) (or Remark \ref{coercivity}(c) related to (b)) holds};\\
\end{array}
\right.$$
Then $\mathfrak{C}^{\star}>0$. Since $u\in\mathcal{W}_2(\Omega;\Gamma)$ satisfies the inequality
(\ref{form-Ineq}), proceeding as in Proposition \ref{cont-coercive-form} and Remark \ref{coercivity}, we obtain that
\begin{equation}
\label{non-neg}|\|\mathbf{u}^-\||^2_{_{2}}
\,\leq\,c\left(\mathcal{E}_{\mu}(u^-,u^-)-\mathfrak{C}^{\star}
\|u^-\|^2_{_{2,\Omega}}\right)\,\leq\,-c\,\mathcal{E}_{\mu}(u,u^-)\,\leq0,
\end{equation}
for some constant $c>0$. Thus $\mathbf{u}^-=\mathbf{0}$, which shows that $\mathbf{u}\geq\mathbf{0}$ a.e., as desired.

\label{A-operator-prop}
 The operator $\mathbf{A}$ is resolvent positive. More precisely, the operator
 $\lambda-\mathbf{A}$ on $D(\mathbf{A})$ is invertible for all $\gamma>\mathfrak{C}^{\star}_0$, where
 $$\mathfrak{C}^{\star}_0:=\left\{
\begin{array}{lcl}
\delta^{\star}_0,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\textrm{if Remark \ref{coercivity}(a) holds},\\
\delta^{\star}_0C_{\tau^{\ast}},\,\,\,\,\,\,\,\,\textrm{if Remark \ref{coercivity}(b) holds}
\end{array}
\right.$$
(where we recall the definition of $\delta^{\star}_0>0$ given in (\ref{delta-star})),
 and if $\mathbf{A}(u,0)=(f,g)$ for $(f,g)\in\mathbb{X\!}^{\,2}(\Omega,\Gamma)$ are such that
 $f\geq0$ and $g\geq0$, then $u\geq 0$ a.e. Moreover,
if $D(\mathbf{A})$ is equipped with the graph norm, then $D(\mathbf{A})$ is continuously embedded into $\mathcal{W}_2(\Omega;\Gamma)\times \{0\}.$

\label{classical sol}
Let $I=[0,T]$ or $I=[0,\infty]$.
\begin{enumerate}
\item[(a)]\,\, We say that function $u$ is a \textbf{classical solution  of problem (\ref{1.06})}, if
$u\in C^1((0,T], L^2(\Omega))$ with  $u(0)=u_0,$  the mapping $t\to (u(t),0)$ lies in $C(I,D(\mathbf{A}))$, and
$$(u_t(\xi),0)- \mathbf{A}(u(\xi),0)=(f(\xi,x), g(\xi,x)),\,\,\,\,\,\,\,\,\textrm{for all}\,\,\xi\in I.$$
\item[(b)]\,\,We call $u$ is a \textbf{mild solution of problem (\ref{1.06})},
if $u\in  C(I, L^2(\Omega)))$ with  $(\int_{0}^{t}u(\xi)\,d\xi, 0) \in D(\mathbf{A})$ for all $t\geq 0$, and
\begin{center}
$(u(t)-u_0, 0)-\mathbf{A}(\int_{0}^{t}u(\xi)\,d\xi, 0)=(\int_{0}^{t} f(\xi,x)\,d\xi,\int_{0}^{t} g(\xi,x)\,d\xi)$.
\end{center}
\end{enumerate}

\label{clas-stron-weak-mild}
Let $I=[0,T]$ or $I=[0,\infty).$ Then every classical solution of problem (\ref{1.06}) on $I$ is a weak solution of problem (\ref{1.06}) on $I$, and
every weak solution of equation (\ref{1.06}) on $I$ is a mild solution of the heat equation (\ref{1.06}) on $I.$

\label{apriori estimates}
Let $u$ be a classical solution of (\ref{1.06}) on $[0,T],$ for some $T>0$. Then\\[2ex]
$\displaystyle\sup_{t\in [0,T]}\displaystyle\int_{\Omega} |u(t)|^2 dx +\displaystyle\int_{0}^{T}\|\nabla u(\xi)\|^2_{_{2,\Omega}}\,d\xi+
\displaystyle\int^T_{0}\|u(\xi)\|^2_{_{D(\Lambda_{_{\Gamma}})}}\,d\xi$\\
\begin{equation}\label{aux-estimate}
\leq\,c\left(\|u_0\|^2_{_{2,\Omega}}+\displaystyle\int_{0}^{T}\|f(\xi)\|^2_{_{2,\Omega}}d\xi+\displaystyle\int_{0}^{T}\|g(\xi)\|^2_{_{2,\Gamma}}d\xi\right),
\end{equation}
where $c$ is a positive constant depending on $T,\,|\Omega|,\,\gamma,\,\bar{\alpha}.$

\label{exist-uniq-weak-soln}
Given $T>0$ arbitrary fixed, let $u_0\in L^2(\Omega)$,\, $f\in L^2(0,T; L^2(\Omega))$ and $g\in L^2(0,T,L^2_{\mu}(\Gamma))$.
Then there exists a weak solution of (\ref{1.06}) in $[0,T]$ which is unique, even in the class of mild solutions.

\label{Lem1}
Given $T>0$ fixed, let $u\in L^{\infty}(-T,0;L^2(\Omega))\cap L^2(-T,0;\mathcal{W}_2(\Omega;\Gamma))$, and assume that
$u_k(t)\in L^{\infty}(-T,0;L^2(\Omega))\cap L^2(-T,0;D(\Lambda_{_{\Gamma}}))$. Given $K_1,\,K_2\geq1$ integers and
$\xi\in\{1,\ldots,K_1\}$, and $\zeta\in\{1,\ldots,K_2\}$, let $r_{1,\xi}\in[2,\infty)$, \,$s_{1,\xi}\in[2,2N(N-2)^{-1}]$,\,
$r_{2,\zeta}\in[2,\infty)$, \,$s_{2,\zeta}\in[2,2d(N-2)^{-1}]$, such that
\begin{equation}\label{Lem1-01}
\displaystyle\frac{1}{r_{1,\xi}}+\displaystyle\frac{N}{2s_{1,\xi}}=\displaystyle\frac{N}{4}\,\,\,\,\,\textrm{and}
\,\,\,\,\,\displaystyle\frac{1}{r_{2,\zeta}}+\displaystyle\frac{d}{2s_{2,\zeta}}=\displaystyle\frac{N}{4}.
\end{equation}
Assume that there exists constants $\hat{k}_0,\,\gamma_0\geq0$ and positive numbers $\theta_{1,\xi},\,\theta_{2,\zeta}$, such that
for all $\varsigma\in(0,T]$,\, $\varepsilon\in(0,1/2)$, and $k\geq\hat{k}_0$, we have\\[2ex]
$\Upsilon^2_{(1-\varepsilon)\varsigma}(u_k)\,\leq\,\displaystyle\frac{\gamma_0}{\varepsilon\varsigma}
\displaystyle\int^0_{-\varsigma}\displaystyle\int_{\Omega}|u_k(t)|^2\,dx\,dt+$\\
\begin{equation}\label{Lem1-02}
+\gamma_0k^2\displaystyle\sum^{K_1}_{\xi=1}\left(\displaystyle\int^0_{-\varsigma}|\Omega_k(t)|
^{^{\frac{r_{1,\xi}}{s_{1,\xi}}}}\,dt\right)^{^{\frac{2(1+\theta_{1,\xi})}{r_{1,\xi}}}}
+\gamma_0k^2\displaystyle\sum^{K_2}_{\zeta=1}\left(\displaystyle\int^0_{-\varsigma}\mu(\Gamma_k(t))
^{^{\frac{r_{2,\zeta}}{s_{2,\zeta}}}}\,dt\right)^{^{\frac{2(1+\theta_{2,\zeta})}{r_{2,\zeta}}}}.
\end{equation}
Then there exists a constant $C^{\ast}_0>0$ (independent of $u$ and $\hat{k}_0$) such that
\begin{equation}\label{Lem1-03}
\textrm{ess}\displaystyle\sup_{\left[-\frac{T}{2},0\right]\times\overline{\Omega}}[u]
\,\leq\,C^{\ast}_0\left(\|u\|^2_{_{L^{2}(-T,0;L^{2}(\Omega))}}+\hat{k}^2_0\right)^{1/2}.
\end{equation}
Moreover, if instead of (\ref{Lem1-02}) one has\\[2ex]
$\Upsilon^2_{_T}(u_k)\,\leq\,\gamma_0\displaystyle\int^0_{-T}\displaystyle\int_{\Omega}|u_k(t)|^2\,dx\,dt+$\\
\begin{equation}\label{Lem1-04}
+\gamma_0k^2\displaystyle\sum^{K_1}_{\xi=1}\left(\displaystyle\int^0_{-T}|\Omega_k(t)|
^{^{\frac{r_{1,\xi}}{s_{1,\xi}}}}\,dt\right)^{^{\frac{2(1+\theta_{1,\xi})}{r_{1,\xi}}}}
+\gamma_0k^2\displaystyle\sum^{K_2}_{\zeta=1}\left(\displaystyle\int^0_{-T}\mu(\Gamma_k(t))
^{^{\frac{r_{2,\zeta}}{s_{2,\zeta}}}}\,dt\right)^{^{\frac{2(1+\theta_{2,\zeta})}{r_{2,\zeta}}}},
\end{equation}
Then there exists a constant $C^{\star}>0$ (independent of $u$ and $k_0$) such that
\begin{equation}\label{Lem1-05}
\textrm{ess}\displaystyle\sup_{\left[-T,0\right]\times\overline{\Omega}}[u]
\,\leq\,C^{\ast}_0\left(\|u\|^2_{_{L^{2}(-T,0;L^{2}(\Omega))}}+\hat{k}^2_0\right)^{1/2}.
\end{equation}

The proof is a direct modification of \cite[Theorem A.2 and Corollary A.3]{NITTKA2014} to the case of irregular domains. However, for the sake of completeness we provide a complete proof here.
We begin by observing that since $|\Omega_k(t)|\leq|\Omega|$ and $\mu(\Gamma_k(t))\leq\mu(\Gamma)$, it suffices to consider
$$\theta_{1,\xi}=\theta_{2,\zeta}=\theta:=\min\left\{\min\{\theta_{1,\xi}\mid1\leq\xi\leq K_1\}\cup\min\{\theta_{2,\zeta}\mid1\leq\zeta\leq K_2\}\right\}$$
for each $\xi\in\{1,\ldots,K_1\}$ and $\zeta\in\{1,\ldots,K_2\}$, provided that $\gamma_0$ is replaced by a larger constant $\gamma'_0$
(depending on $r_{1,\xi}$,\, $s_{1,\xi}$,\, $\theta_{1,\xi}$,\, $r_{2,\zeta}$,\, $s_{2,\zeta}$,\, $\theta_{2,\zeta}$,\, $T$,\, $\gamma_0$,\, $|\Omega|$,
$\mu(\Gamma)$), since by performing this selection, both inequalities (\ref{Lem1-02}) and (\ref{Lem1-04}) still hold. Then, given $\hat{k}>\hat{k}_0\geq0$ fixed,
define the sequences $\{\varsigma_n\}_{n\geq0}$,\, $\{k_n\}_{n\geq0}$,\, $\{y_n\}_{n\geq0}$,\, $\{z_n\}_{n\geq0}$ of positive real numbers, by:
\begin{equation}\label{Lem1-06}
\varsigma_n:=\displaystyle\frac{T}{2}(1+2^{-(n+1)}),\,\,\,\,\,\,k_n:=(2-2^{-n})\hat{k},\,\,\,\,\,\,
y_n:=\displaystyle\frac{1}{\hat{k}^2}\displaystyle\int^0_{-\varsigma_n}\displaystyle\int_{\Omega}|u_{k_n}(t)|^2\,dx\,dt,
\end{equation}
and
\begin{equation}\label{Lem1-07}
z_n:=\displaystyle\sum^{K_1}_{\xi=1}\left(\displaystyle\int^0_{-\varsigma_n}|\Omega_{k_n}(t)|
^{^{\frac{r_{1,\xi}}{s_{1,\xi}}}}\,dt\right)^{^{\frac{2}{r_{1,\xi}}}}
+\displaystyle\sum^{K_2}_{\zeta=1}\left(\displaystyle\int^0_{-\varsigma_n}\mu(\Gamma_{k_n}(t))
^{^{\frac{r_{2,\zeta}}{s_{2,\zeta}}}}\,dt\right)^{^{\frac{2}{r_{2,\zeta}}}}.
\end{equation}
Clearly $\varsigma_n\in[T/2,T]$ and $k_n\geq\hat{k}_0$ for each nonnegative integer $n$. Moreover, it is clear that
$$|u_{k_n}(t)|\geq(k_{n+1}-k_n)\chi_{_{\overline{\Omega}_{k_{n+1}}(t)}},$$ so taking into account
the definitions of the sequences defined above together with H\"older's inequality and (\ref{Sobolev-parabolic}), we calculate and get that\\[2ex]
$\hat{k}^2y_{n+1}\,\leq\,\left(\displaystyle\int^0_{-\varsigma_{n+1}}|\Omega_{k_{n+1}}(t)|\,dt\right)^{1/N}
\left(\displaystyle\int^0_{-\varsigma_{n+1}}\left\{\displaystyle\int_{\Omega}\left|u_{k_{n+1}}(t)\right|^{^{\frac{2N}{N-1}}}\,dx\right\}^{^{\frac{N-1}{N}}}dt\right)$\\
\begin{equation}\label{Lem1-08}
\leq\,c\left(\displaystyle\int^0_{-\varsigma_{n+1}}|\Omega_{k_{n+1}}(t)|\,dt\right)^{1/N}\Upsilon^2_{\varsigma_{n+1}}(u_{k_{n+1}})
\,\leq\,c\left\{(k_{n+1}-k_n)^{-2}\hat{k}^2y_n\right\}^{1/N}\Upsilon^2_{\varsigma_{n+1}}(u_{k_{n+1}})
\,\leq\,c\,4^{n+1}y_n^{1/N}\Upsilon^2_{\varsigma_{n+1}}(u_{k_{n+1}}),
\end{equation}
where $c>0$ is a constant that varies from line to line (this will be assumed for the remaining of the proof). In the same way, we get that\\[2ex]
$4^{-(n+1)}\hat{k}^2z_{n+1}\,=\,(k_{n+1}-k_n)^2z_{n+1}$\\
\begin{equation}\label{Lem1-09}\leq\,\displaystyle\sum^{K_1}_{\xi=1}\left(\displaystyle\int^0_{-\varsigma_{n+1}}\left\{\displaystyle\int_{\Omega}|u_{k_n}(t)|^{s_{1,\xi}}\,dx\right\}
^{^{\frac{r_{1,\xi}}{s_{1,\xi}}}}\,dt\right)^{^{\frac{2}{r_{1,\xi}}}}
+\displaystyle\sum^{K_2}_{\zeta=1}\left(\displaystyle\int^0_{-\varsigma_{n+1}}\left\{\displaystyle\int_{\Gamma}|u_{k_n}(t)|^{s_{2,\zeta}}\,d\mu\right\}
^{^{\frac{r_{2,\zeta}}{s_{2,\zeta}}}}\,dt\right)^{^{\frac{2}{r_{2,\zeta}}}}\,\leq\,c\,\Upsilon^2_{\varsigma_{n+1}}(u_{k_{n}}).
\end{equation}
Now, taking $\varsigma=\varsigma_n$ and $\varepsilon=1-\varsigma_{n+1}/\varsigma_n\geq2^{-(n+3)}$, we apply the assumption (\ref{Lem1-02})
to obtain that
\begin{equation}\label{Lem1-10}
\Upsilon^2_{\varsigma_{n+1}}(u_{k_{n+1}})\,\leq\,\Upsilon^2_{\varsigma_{n+1}}(u_{k_{n}})\,\leq\,
\frac{\gamma_0}{\varepsilon\varsigma_n}\hat{k}^2y_n+\gamma_0k^2_nz^{1+\theta}_n
\,\leq\,\gamma_02^{n+4}\hat{k}^2(T^{-1}+1)(y_n+z^{1+\theta}_n),
\end{equation}
and then combining (\ref{Lem1-08}), (\ref{Lem1-09}), and (\ref{Lem1-10}), we arrive at
\begin{equation}\label{Lem1-11}
y_{n+1}\,\leq\,c'\,8^n(y^{1+\delta}_n+z^{1+\theta}_ny^{\delta}_n)\,\,\textrm{and}\,\,
z_{n+1}\,\leq\,c'\,8^n(y_n+z^{1+\theta}_n),\,\,\textrm{for each integer}\,\,n\geq0,
\end{equation}
for some constant $c'>0$, where $\delta:=1/N$. To complete the arguments, we seek estimations for $y_0$ and $z_0$. In fact, we easy see that
\begin{equation}\label{Lem1-12}
y_0=\displaystyle\frac{1}{\hat{k}^2}\displaystyle\int^0_{-\frac{3T}{4}}\displaystyle\int_{\Omega}|u_{k_0}(t)|^2\,dx\,dt\,\leq\,
\displaystyle\frac{1}{\hat{k}^2}\displaystyle\int^0_{-T}\displaystyle\int_{\Omega}|u(t)|^2\,dx\,dt.
\end{equation}
On the other hand, using (\ref{Lem1-02}) and following the approach as in (\ref{Lem1-08}) and (\ref{Lem1-09}), we have that\\[2ex]
$(\hat{k}-\hat{k}_0)^2z_0\,\leq\,\displaystyle\sum^{K_1}_{\xi=1}\left(\displaystyle\int^0_{-\varsigma_{0}}\left\{\displaystyle\int_{\Omega}|u_{k_0}(t)|^{s_{1,\xi}}\,dx\right\}
^{^{\frac{r_{1,\xi}}{s_{1,\xi}}}}\,dt\right)^{^{\frac{2}{r_{1,\xi}}}}+
\displaystyle\sum^{K_2}_{\zeta=1}\left(\displaystyle\int^0_{-\varsigma_{0}}\left\{\displaystyle\int_{\Gamma}|u_{k_0}(t)|^{s_{2,\zeta}}\,d\mu\right\}
^{^{\frac{r_{2,\zeta}}{s_{2,\zeta}}}}\,dt\right)^{^{\frac{2}{r_{2,\zeta}}}}$\\
$$\leq\,c\,\Upsilon^2_{\varsigma_{0}}(u_{k_{0}})
\leq\,\displaystyle\frac{4c\gamma_0}{T}\displaystyle\int^0_{-T}\displaystyle\int_{\Omega}|u_{k_0}(t)|^2\,dx\,dt+
c\gamma_0k^2_0\displaystyle\sum^{K_1}_{\xi=1}\left[T|\Omega|^{^{\frac{r_{1,\xi}}{s_{1,\xi}}}}\right]^{^{\frac{2(1+\theta)}{r_{1,\xi}}}}
+\,c\gamma_0k^2_0\displaystyle\sum^{K_2}_{\zeta=1}\left[T\mu(\Gamma)^{^{\frac{r_{2,\zeta}}{s_{2,\zeta}}}}\right]^{^{\frac{2(1+\theta)}{r_{2,\zeta}}}}.$$
Thus letting
$$c'':=c\gamma_0\max\left\{\frac{4}{T}\,,\,\displaystyle\sum^{K_1}_{\xi=1}\left[T|\Omega|^{^{\frac{r_{1,\xi}}{s_{1,\xi}}}}\right]^{^{\frac{2(1+\theta)}{r_{1,\xi}}}}
+\displaystyle\sum^{K_2}_{\zeta=1}\left[T\mu(\Gamma)^{^{\frac{r_{2,\zeta}}{s_{2,\zeta}}}}\right]^{^{\frac{2(1+\theta)}{r_{2,\zeta}}}}\right\},$$
we arrive at
\begin{equation}\label{Lem1-13}
z_0\,\leq\,\displaystyle\frac{c''}{(\hat{k}-\hat{k}_0)^2}\left(\displaystyle\int^0_{-T}\displaystyle\int_{\Omega}|u_{k_0}(t)|^2\,dx\,dt+k^2_0\right),
\,\,\,\,\,\,\,\,\,\,\,\,\textrm{for all}\,\,\,\hat{k}\geq k_0.
\end{equation}
Then, we define $$d:=\min\left\{\delta,\,\frac{\theta}{1+\theta}\right\}\,\,\,\,\,\textrm{and}\,\,\,\,\,
\eta:=\min\left\{\frac{1}{(2c')^{^{\frac{1}{\delta}}}8^{^{\frac{1}{\delta d}}}},\,\frac{1}{(2c')^{^{\frac{1+\theta}{\theta}}}\,8^{^{\frac{1}{\theta d}}}}\right\},$$
and then choose
\begin{equation}\label{Lem1-14}
\hat{k}:=\max\left\{\displaystyle\frac{1}{\sqrt{\eta}}\left(\displaystyle\int^0_{-T}\displaystyle\int_{\Omega}|u(t)|^2\,dx\,dt\right)^{1/2},\,
\displaystyle\frac{\sqrt{c_1}}{\eta^{^{\frac{1}{2(1+\theta)}}}}
\left(\displaystyle\int^0_{-T}\displaystyle\int_{\Omega}|u(t)|^2\,dx\,dt+\hat{k}^2_0\right)^{1/2}+\hat{k}_0\right\}.
\end{equation}
Then one sees that
\begin{equation}\label{Lem1-15}
\hat{k}\,\leq\,c^{\star}\left(\displaystyle\int^0_{-T}\displaystyle\int_{\Omega}|u(t)|^2\,dx\,dt+\hat{k}^2_0\right)^{1/2}
\end{equation}
for some constant $c^{\star}>0$, and moreover the selection implies that
\begin{equation}\label{Lem1-16}
y_0\,\leq\,\eta\,\,\,\,\,\,\,\,\textrm{and}\,\,\,\,\,\,\,\,z_0\,\leq\,\eta^{^{\frac{1}{1+\theta}}}.
\end{equation}
In views of (\ref{Lem1-11}) and (\ref{Lem1-16}), we see that the sequences $\{y_n\}$,\, $\{z_n\}$ satisfy the conditions of Lemma \ref{lemma2}.
Thus, applying Lemma \ref{lemma2} for $\hat{k}$ given by (\ref{Lem1-14})
shows that $\displaystyle\lim_{n\rightarrow\infty}z_n=0$, and consequently
\begin{equation}\label{Lem1-17}
u(t)\,\leq\,\displaystyle\lim_{n\rightarrow\infty}k_n=2\hat{k}\,\,\,\,\textrm{a.e. in}\,\,\overline{\Omega},\,\,\,\,\,\textrm{for a.e.}\,\,
t\in\displaystyle\bigcap_{n\in\mathbb{N\!}}[-\varsigma_n,0]=[-T/2,0].
\end{equation}
Combining (\ref{Lem1-17}) with (\ref{Lem1-15}), we get that
\begin{equation}\label{Lem1-18}
\displaystyle\textrm{ess}\hspace{-0.70cm}\sup_{(t,x)\in\left[-\frac{T}{2},0\right]\times\Omega}\{u(t,x)\}+
\displaystyle\textrm{ess}\hspace{-0.60cm}\sup_{(t,x)\in\left[-\frac{T}{2},0\right]\times\Gamma}\{u(t,x)\}
\,\leq\,C^{\ast}\left(\displaystyle\int^0_{-T}\displaystyle\int_{\Omega}
|u(t)|^2\,dx\,dt+\hat{k}_0\right)^{1/2}.
\end{equation}
This gives (\ref{Lem1-03}). To complete the proof,
assume now that (\ref{Lem1-04}) is valid. Then by selecting $\varsigma_n:=T$ in the previous arguments, the proof runs in the exact way as in the previous case.
In particular, one has that (\ref{Lem1-17}) is valid for almost all $t\in\displaystyle\bigcap_{n\in\mathbb{N\!}}[-\varsigma_n,0]=[-T,0]$, leading to
the inequality
\begin{equation}\label{Lem1-19}
\displaystyle\textrm{ess}\hspace{-0.63cm}\sup_{(t,x)\in\left[-T,0\right]\times\Omega}\{u(t,x)\}+
\displaystyle\textrm{ess}\hspace{-0.60cm}\sup_{(t,x)\in\left[-T,0\right]\times\Gamma}\{u(t,x)\}
\,\leq\,C^{\star}\left(\displaystyle\int^T_{0}\displaystyle\int_{\Omega}
|u(t)|^2\,dx\,dt+\hat{k}_0\right)^{1/2}.
\end{equation}
This completes the proof.

\label{Thm-Partial-Bounded}
Assume that conditions {\bf (A3)'} and {\bf (B4)'} hold.
Given $T>0$ fixed, let $\kappa_1,\,\kappa_2,\,p,\,q\in[2,\infty)$ be such that
\begin{equation}\label{Thm1-00}
\displaystyle\frac{1}{\kappa_1}+\displaystyle\frac{N}{2p}<1\,\,\,\,\,\,\,\,\textrm{and}
\,\,\,\,\,\,\,\,\displaystyle\frac{1}{\kappa_2}+\displaystyle\frac{d}{2q(d+2-N)}<\frac{1}{2}.
\end{equation}
Given $u_0\in L^2(\Omega)$, let $f\in L^{\kappa_1}(0,T;L^p(\Omega))$ and $g\in L^{\kappa_2}(0,T;L^q_{\mu}(\Gamma))$, and
let $u\in C(0,T;L^2(\Omega))\cap L^2(0,T;\mathcal{W}_2(\Omega;\Gamma))$ be a weak solution of problem (\ref{1.06}).
Then there exists a constant $C^{\ast}_1=C^{\ast}_1(T,N,d,\kappa_1,\kappa_2,p,q,|\Omega|,\mu(\Gamma))>0$ such that
\begin{equation}\label{Thm1-01}
|\|\mathbf{u}\||_{_{L^{\infty}(T/2,T;\mathbb{X\!}^{\,\infty}(\Omega;\Gamma))}}
\,\leq\,C^{\ast}_1\left(\|u\|_{_{L^{2}(0,T;L^{2}(\Omega))}}+\|f\|_{_{L^{\kappa_1}(0,T;L^{p}(\Omega))}}+
\|g\|_{_{L^{\kappa_2}(0,T;L^{q}_{\mu}(\Gamma))}}\right).
\end{equation}
If in addition $u_0=0$, then we get the global estimate
\begin{equation}\label{Thm1-02}
|\|\mathbf{u}\||_{_{L^{\infty}(0,T;\mathbb{X\!}^{\,\infty}(\Omega;\Gamma))}}
\,\leq\,C^{\ast}_1\left(\|u\|_{_{L^{2}(0,T;L^{2}(\Omega))}}+\|f\|_{_{L^{\kappa_1}(0,T;L^{p}(\Omega))}}+
\|g\|_{_{L^{\kappa_2}(0,T;L^{q}_{\mu}(\Gamma))}}\right).
\end{equation}

Let $u\in C(0,T;L^2(\Omega))\cap L^2(0,T;\mathcal{W}_2(\Omega;\Gamma))$ be a weak solution of problem (\ref{1.06}).
The proof of this result is technical and long, and will be divided into three main steps.\\
$\bullet$\,\, {\it \underline{Step 1}}. Assume in addition that $u\in C(0,T;L^2(\Omega))\cap L^2(0,T;\mathcal{W}_2(\Omega;\Gamma))$
is a classical solution of (\ref{1.06}), and that $T\leq T_0$ for some constant $T_0>0$ (depending only in $N$, $d$, $\kappa_1$,
$\kappa_2$, $p$, $q$, $|\Omega|$, $\mu(\Gamma)$, and the coefficients of the operators $\mathcal{A}$ and $\mathcal{B}$). By a linear
translation in time, we may assume that problem (\ref{1.06}) is solved over $[-T,0]$, with initial value $u_0=u(-T)$.
Let $u_k(t)$ be the function given by (\ref{2.16}), fix $\varsigma\in[-T,0]$, and select a function $\psi\in H^1(-\varsigma,0)$
such that $0\leq\psi(t)\leq1$ for all $t\in[-\varsigma,0]$. Assume in addition that either $\psi(-\varsigma)=0$, or $\varsigma=T$ and
$u_k(-T)=0$. Then for each $t\in[-\varsigma,0]$, observe that\\[2ex]
$\displaystyle\frac{\psi(t)^2}{2}\displaystyle\int_{\Omega_k(t)}|u_k(t)|^2\,dx=\displaystyle\int^t_{-\varsigma}
\displaystyle\frac{d}{d\xi}\left(\displaystyle\frac{\psi(\xi)^2}{2}\displaystyle\int_{\Omega_k(\xi)}|u_k(\xi)|^2\,dx\right)d\xi$\\
\begin{equation}\label{thm1-02}
=\displaystyle\int^t_{-\varsigma}\psi(\xi)\psi'(\xi)\left(\displaystyle\int_{\Omega_k(\xi)}|u_k(\xi)|^2\,dx\right)d\xi+
\displaystyle\int^t_{-\varsigma}\psi(\xi)^2\left(\displaystyle\int_{\Omega_k(\xi)}u_k(\xi)\frac{ du_k(\xi)}{d\xi}\,dx\right)d\xi.
\end{equation}
Now, using the fact that $u\in C(0,T;L^2(\Omega))\cap L^2(0,T;\mathcal{W}_2(\Omega;\Gamma))$
is a classical solution of (\ref{1.06}), we see that
\begin{equation}\label{thm1-03}
\displaystyle\int_{\Omega_k(\xi)}u_k(\xi)\frac{ du_k(\xi)}{d\xi}\,dx=\displaystyle\int_{\Omega_k(\xi)}u_k(\xi)\frac{ du(\xi)}{d\xi}\,dx
=\displaystyle\int_{\Omega_k(\xi)}f(\xi,x)u_k(\xi)\,dx+\displaystyle\int_{\Gamma_k(\xi)}g(\xi,x)u_k(\xi)\,d\mu-\mathcal{E}_{\mu}(u(\xi),u_k(\xi)),
\end{equation}
where we recall the definition of the form $\mathcal{E}_{\mu}(\cdot,\cdot)$ in (\ref{3.1.01}). Estimating the right hand side in (\ref{thm1-03}) and taking
into account Assumptions {\bf (A3)'} and {\bf (B4)'}, we see that\\[2ex]
$\mathcal{E}_{\mu}(u(\xi),u_k(\xi))\,\geq\,\mathcal{E}_{_{\Omega}}(u_k(\xi),u_k(\xi))+\min\{1,c^{\star}_1\}\mathcal{E}_{_{\Gamma}}(u_k(\xi),u_k(\xi))+$\\
$$+\displaystyle\int_{\Omega_k(\xi)}\displaystyle\sum^N_{i=1}\hat{a}_ik\partial_{x_i}u_k(\xi)\,dx+\displaystyle\int_{\Omega_k(\xi)}\lambda ku_k(\xi)\,dx
+\min\{1,c^{\star}_1\}\displaystyle\int_{\Gamma_k(\xi)}\beta ku_k(\xi)\,d\mu+$$
\begin{equation}\label{thm1-04}
+c^{\star}_2\|u_k(\xi)\|^2_{_{D(\Lambda_{_{\Gamma}})}}-c^{\star}_3\displaystyle\int_{\Gamma_k(t)}\rho(x)(|u_k(t)|^2+k^2)\,d\mu,
\end{equation}
where the constants $c^{\star}_m$ ($m\in\{1,2,3\}$) and the function $\rho$ are described in condition {\bf (B4)'}.
Recalling (\ref{1.04}), we apply Young's inequality multiple times and use Remark \ref{R-embedding}(d) to produce the following estimates.\\[2ex]
$c_0\|\nabla u_k(\xi)\|^2_{_{2,\Omega_k(\xi)}}\,\leq\,\mathcal{E}_{_{\Omega}}(u_k(\xi),u_k(\xi))+\|\hat{\mathfrak{a}}\|_{_{r_1,\Omega}}
\|u_k(\xi)\|_{_{\frac{2r_1}{r_1-2},\Omega_k(\xi)}}\|\nabla u_k(\xi)\|_{_{2,\Omega_k(\xi)}}+$\\
$$\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,+\|\check{\mathfrak{a}}\|_{_{r_2,\Omega}}
\|u_k(\xi)\|_{_{\frac{2r_2}{r_2-2},\Omega_k(\xi)}}\|\nabla u_k(\xi)\|_{_{2,\Omega_k(\xi)}}+
\displaystyle\int_{\Omega_k(\xi)}|\lambda||u_k(\xi)|^2\,dx$$
$$\leq\,\mathcal{E}_{_{\Omega}}(u_k(\xi),u_k(\xi))+\|\hat{\mathfrak{a}}\|_{_{r_1,\Omega}}\left(2\epsilon_1\|\nabla u_k(\xi)\|^2_{_{2,\Omega_k(\xi)}}+
\frac{C_{\epsilon^2_1}}{\epsilon_1}\|u_k(\xi)\|^2_{_{2,\Omega_k(\xi)}}\right)+\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,$$
\begin{equation}\label{thm1-05}
+\|\check{\mathfrak{a}}\|_{_{r_2,\Omega}}\left(2\epsilon_1\|\nabla u_k(\xi)\|^2_{_{2,\Omega_k(\xi)}}+
\frac{C'_{\epsilon^2_1}}{\epsilon_1}\|u_k(\xi)\|^2_{_{2,\Omega_k(\xi)}}\right)+\displaystyle\int_{\Omega_k(\xi)}|\lambda||u_k(\xi)|^2\,dx,
\end{equation}
for all $\epsilon_1>0$, for some constant $C_{\epsilon^2_1},\,C'_{\epsilon^2_1}>0$. Writing $C_1:=C_{\epsilon^2_1}$,\, $C_2=C'_{\epsilon^2_1}$,
and $$M^{\star}:=\max\left\{\|\hat{\mathfrak{a}}\|_{_{r_1,\Omega}},\|\check{\mathfrak{a}}\|_{_{r_2,\Omega}}\right\}
\left(C_1\|\hat{\mathfrak{a}}\|_{_{r_1,\Omega}}+C_2\|\check{\mathfrak{a}}\|_{_{r_2,\Omega}}\right)/c_0>0,$$
we insert $\epsilon_1:=c_0\left(8\max\left\{\|\hat{\mathfrak{a}}\|_{_{r_1,\Omega}},\|\check{\mathfrak{a}}\|_{_{r_2,\Omega}}\right\}\right)^{-1}$
into (\ref{thm1-05}) to get that
\begin{equation}\label{thm1-06}
\mathcal{E}_{_{\Omega}}(u_k(\xi),u_k(\xi))\,\geq\,\displaystyle\frac{c_0}{2}\|\nabla u_k(\xi)\|^2_{_{2,\Omega_k(\xi)}}-
\displaystyle\int_{\Omega_k(\xi)}(M^{\star}+|\lambda|)|u_k(\xi)|^2\,dx.
\end{equation}
Also, recalling that the ``Wentzell-type" boundary form $(\Lambda_{_{\Gamma}},D(\Lambda_{_{\Gamma}}))$ is assumed to be weakly coercive,
we get the existence of constants $c^{\ast}_1>0$ and $c^{\ast}_2\in\mathbb{R\!}\,$ such that
\begin{equation}\label{thm1-07}
\mathcal{E}_{_{\Gamma}}(u_k(\xi),u_k(\xi))\,\geq\,c^{\ast}_1\|u_k(\xi)\|^2_{_{D(\Lambda_{_{\Gamma}})}}-
\displaystyle\int_{\Gamma_k(\xi)}(|c^{\ast}_2|+|\beta|)|u_k(\xi)|^2\,d\mu.
\end{equation}
It is also easy to see that
\begin{equation}\label{thm1-08}
\displaystyle\int_{\Omega_k(\xi)}\displaystyle\sum^N_{i=1}\hat{a}_ik\partial_{x_i}u_k(\xi)\,dx\,\geq\,-\displaystyle
\frac{k^2}{c_0}\displaystyle\int_{\Omega_k(\xi)}\displaystyle\sum^N_{i=1}|\hat{a}_i|^2\,dx-\displaystyle
\frac{c_0}{4}\|\nabla u_k(\xi)\|^2_{_{2,\Omega_k(\xi)}},
\end{equation}
and\\[2ex]
\indent$\displaystyle\int_{\Omega_k(\xi)}f(\xi,x)u_k(\xi)\,dx+\displaystyle\int_{\Gamma_k(\xi)}g(\xi,x)u_k(\xi)\,d\mu$\\
\begin{equation}\label{thm1-09}
\leq\,\displaystyle\frac{1}{k}\displaystyle\int_{\Omega_k(\xi)}|f(\xi,x)|(|u_k(\xi)|^2+k^2)\,dx+
\displaystyle\frac{1}{k}\displaystyle\int_{\Gamma_k(\xi)}|g(\xi,x)|(|u_k(\xi)|^2+k^2)\,d\mu.
\end{equation}
Letting $$\mathfrak{h}:=\frac{1}{c_0}\displaystyle\sum^N_{i=1}|\hat{a}_i|^2+M^{\star}+|\lambda|\in L^{^{\min\left\{\frac{r_1}{2},r_3\right\}}}(\Omega)^+$$
and $$\mathfrak{k}:=\min\{1,c^{\star}_1\}(|c^{\ast}_2|+2|\beta|)+c^{\star}_3|\rho|\in L^{^{\min\{s,\theta\}}}_{\mu}(\Gamma)^+,$$
we insert (\ref{thm1-06}), (\ref{thm1-07}), and (\ref{thm1-08}) into (\ref{thm1-04}), to deduce that\\[2ex]
$\mathcal{E}_{\mu}(u(\xi),u_k(\xi))\,\geq\,\displaystyle\frac{c_0}{4}\|\nabla u_k(\xi)\|^2_{_{2,\Omega_k(\xi)}}+
c^{\ast\star}\|u_k(\xi)\|^2_{_{D(\Lambda_{_{\Gamma}})}}$\\
\begin{equation}\label{thm1-10}
-\displaystyle\int_{\Omega_k(\xi)}\mathfrak{h}(|u_k(\xi)|^2+k^2)\,dx-\displaystyle\int_{\Gamma_k(\xi)}\mathfrak{k}(|u_k(\xi)|^2+k^2)\,d\mu,
\end{equation}
where $c^{\ast\star}:=c^{\ast}_1\min\{1,c^{\star}_1\}+c^{\star}_2$.
Substituting this into (\ref{thm1-03}) and recalling (\ref{thm1-09}) gives that\\[2ex]
$\displaystyle\int_{\Omega_k(\xi)}u_k(\xi)\frac{ du_k(\xi)}{d\xi}\,dx\,\leq\,-\displaystyle\frac{c_0}{4}\|\nabla u_k(\xi)\|^2_{_{2,\Omega_k(\xi)}}
-c^{\ast\star}\|u_k(\xi)\|^2_{_{D(\Lambda_{_{\Gamma}})}}$\\
\begin{equation}\label{thm1-11}
+\displaystyle\int_{\Omega_k(\xi)}\left(\frac{1}{k}|f(\xi,x)|+\mathfrak{h}\right)(|u_k(\xi)|^2+k^2)\,dx+
\displaystyle\int_{\Gamma_k(\xi)}\left(\frac{1}{k}|g(\xi,x)|+\mathfrak{k}\right)(|u_k(\xi)|^2+k^2)\,d\mu.
\end{equation}
From here, we insert (\ref{thm1-11}) into (\ref{thm1-02}) to get that\\[2ex]
$\min\left\{\displaystyle\frac{1}{2},\displaystyle\frac{c_0}{4},c^{\ast\star}\right\}\Upsilon^2_{\varsigma}(\psi u_k)
\,\leq\,\displaystyle\sup_{-\varsigma\leq t\leq0}\left(\displaystyle\frac{\psi(t)^2}{2}\|u_k(t)\|^2_{_{2,\Omega_k(t)}}\right)+
\frac{c_0}{4}\displaystyle\int^0_{-\varsigma}\psi(t)^2\|\nabla u_k(t)\|^2_{_{2,\Omega_k(t)}}\,dt\,+\,c^{\ast\star}
\displaystyle\int^0_{-\varsigma}\psi(t)^2\|u_k(t)\|^2_{_{D(\Lambda_{_{\Gamma}})}}\,dt$\\
$$\leq\,L_{\psi'}\displaystyle\int^0_{-\varsigma}\|u_k(t)\|^2_{_{2,\Omega_k(t)}}\,dt
+\displaystyle\int^0_{-\varsigma}\displaystyle\int_{\Omega_k(t)}\left(\frac{1}{k}|f(t,x)|+\mathfrak{h}\right)(\psi(t)^2|u_k(t)|^2+k^2)\,dx\,dt+\,\,\,\,\,$$
\begin{equation}\label{thm1-12}
\indent\indent\indent\indent
+\displaystyle\int^0_{-\varsigma}\displaystyle\int_{\Gamma_k(t)}\left(\frac{1}{k}|g(t,x)|+\mathfrak{k}\right)(\psi(t)^2|u_k(t)|^2+k^2)\,d\mu\,dt,
\end{equation}
where $L_{\psi'}:=\displaystyle\sup_{-\varsigma\leq t\leq0}|\psi'(t)|$. We now seek to estimate the last two terms in (\ref{thm1-12}). For this,
we choose $$\theta_1:=\frac{4\tilde{p}+2\tilde{\kappa}_1N-\tilde{p}\tilde{\kappa}_1N}{\tilde{p}\tilde{\kappa}_1N}>0\,\,\,\,\,
\textrm{and}\,\,\,\,\,\theta_2:=\frac{4\tilde{q}+2\tilde{\kappa}_2d-\tilde{q}\tilde{\kappa}_2N}{\tilde{q}\tilde{\kappa}_2N}>0,$$
where $\tilde{\tau}:=2\tau(\tau-1)^{-1}$ for $\tau\in(1,\infty)$. Then
$$\frac{1}{\tilde{\kappa}_1(1+\theta_1)}+\frac{N}{2\tilde{p}(1+\theta_1)}=\frac{1}{\tilde{\kappa}_2(1+\theta_2)}+\frac{d}{2\tilde{q}(1+\theta_2)}=\frac{N}{4}.$$
Put
\begin{equation}\label{thm1-13}
\hat{k}^2_0:=\|f\|^2_{_{L^{\kappa_1}(0,T;L^{p}(\Omega))}}+\|g\|^2_{_{L^{\kappa_2}(0,T;L^{q}_{\mu}(\Gamma))}},
\end{equation}
and apply H\"older's inequality to deduce that
$$\displaystyle\int^0_{-\varsigma}\displaystyle\int_{\Omega_k(t)}\frac{1}{k}|f(t,x)|\psi(t)^2|u_k(t)|^2\,dx\,dt
\,\leq\,\displaystyle\frac{1}{k}\|f\|_{_{L^{\kappa_1}(-\varsigma,0;L^{p}(\Omega))}}\|\psi u_k\|^2_{_{L^{\tilde{\kappa}_1}(-\varsigma,0;L^{\tilde{p}}(\Omega))}}$$
\begin{equation}\label{thm1-14}
\leq\,\displaystyle\frac{\hat{k}_0}{k}\left(\displaystyle\int^0_{-\varsigma}|\Omega_k(t)|^{\tilde{\kappa}_1/\tilde{p}}dt\right)^{^{\frac{2\kappa_1\theta_1}{1+\theta_1}}}
\|\psi u_k\|^2_{_{L^{\tilde{\kappa}_1(1+\theta_1)}(-\varsigma,0;L^{\tilde{p}(1+\theta_1)}(\Omega))}}.
\end{equation}
Now observe that $$\displaystyle\lim_{\varsigma\rightarrow0^+}\left\{\left(\displaystyle\int^0_{-\varsigma}|\Omega_k(t)|^{\tilde{\kappa}_1/\tilde{p}}dt\right)
^{^{\frac{2\kappa_1\theta_1}{1+\theta_1}}}\|\psi u_k\|^2_{_{L^{\tilde{\kappa}_1(1+\theta_1)}(-\varsigma,0;L^{\tilde{p}(1+\theta_1)}(\Omega))}}\right\}=0,$$
so using this together with the selection of $\theta_1$ and (\ref{Sobolev-parabolic}) entail the existence of a constant
$T_1=T_1(N,\kappa_1,\theta_1,p,|\Omega|)>0$ such that
\begin{equation}\label{thm1-15}
\displaystyle\int^0_{-\varsigma}\displaystyle\int_{\Omega_k(t)}\frac{1}{k}|f(t,x)|\psi(t)^2|u_k(t)|^2\,dx\,dt
\,\leq\,\displaystyle\frac{\hat{k}_0}{8k}\min\left\{\displaystyle\frac{1}{2},\displaystyle\frac{c_0}{4},c^{\ast\star}\right\}\Upsilon^2_{\varsigma}(\psi u_k)
\end{equation}
whenever $\varsigma\leq T_1$. Also, since $\mathfrak{h}\in L^{^{\min\left\{\frac{r_1}{2},r_3\right\}}}(\Omega)$ and
$$\mathfrak{r}:=2\min\{r_1/2,\,r_3\}\left(\min\{r_1/2,\,r_3\}-1\right)^{-1}<
2N(N-2)^{-1},$$ proceeding in the same way as in the derivation of (\ref{thm1-15}), we get the existence of a constant
$T_2=T_2(N,\min\{r_1/2,\,r_3\},\mathfrak{h},|\Omega|)>0$ fulfilling
\begin{equation}\label{thm1-16}
\displaystyle\int^0_{-\varsigma}\displaystyle\int_{\Omega_k(t)}\mathfrak{h}\psi(t)^2|u_k(t)|^2\,dx\,dt\,
\leq\,\|\mathfrak{h}\|_{_{\min\left\{\frac{r_1}{2},r_3\right\},\Omega}}\|\psi u_k\|^2_{_{L^{2}(-\varsigma,0;L^{\mathfrak{r}}(\Omega))}}
\,\leq\,\displaystyle\frac{1}{8}\min\left\{\displaystyle\frac{1}{2},\displaystyle\frac{c_0}{4},c^{\ast\star}\right\}\Upsilon^2_{\varsigma}(\psi u_k)
\end{equation}
for $\varsigma\leq T_2$. Moreover, recalling the selection of $\theta_2$, and using the fact that $\mathfrak{k}\in L^{^{\min\{s,\theta\}}}_{\mu}(\Gamma)$ with
$$\mathfrak{s}:=2\min\{s,\theta\}\left(\min\{s,\theta\}-1\right)^{-1}<2d(N-2)^{-1},$$ we proceed in the exact way as above to deduce the existence
of positive constants $T_3=T_3(N,d,\kappa_2,\theta_2,q,\mu(\Gamma))$ and $T_4=T_4(N,d,\min\{s,\theta\},\mathfrak{k},\mu(\Gamma))$ such that
\begin{equation}\label{thm1-17}
\displaystyle\int^0_{-\varsigma}\displaystyle\int_{\Gamma_k(t)}\frac{1}{k}|g(t,x)|\psi(t)^2|u_k(t)|^2\,d\mu\,dt
\,\leq\,\displaystyle\frac{\hat{k}_0}{8k}\min\left\{\displaystyle\frac{1}{2},\displaystyle\frac{c_0}{4},c^{\ast\star}\right\}\Upsilon^2_{\varsigma}(\psi u_k),
\end{equation}
if $\varsigma\leq T_3$, and
\begin{equation}\label{thm1-18}
\displaystyle\int^0_{-\varsigma}\displaystyle\int_{\Gamma_k(t)}\mathfrak{k}\psi(t)^2|u_k(t)|^2\,d\mu\,dt\,
\leq\,\|\mathfrak{k}\|_{_{\min\{s,\theta\},\Gamma}}\|\psi u_k\|^2_{_{L^{2}(-\varsigma,0;L^{\mathfrak{s}}_{\mu}(\Gamma))}}
\,\leq\,\displaystyle\frac{1}{8}\min\left\{\displaystyle\frac{1}{2},\displaystyle\frac{c_0}{4},c^{\ast\star}\right\}\Upsilon^2_{\varsigma}(\psi u_k),
\end{equation}
whenever $\varsigma\leq T_4$. Letting $T_0:=\min\{T_1,T_2,T_3,T_4\}$, and taking $\varsigma\in(0,T_0]$ and $k\geq\hat{k}_0$, we insert
(\ref{thm1-15}), (\ref{thm1-16}), (\ref{thm1-17}), and (\ref{thm1-18}) into (\ref{thm1-12}), to arrive at\\[2ex]
$\Upsilon^2_{\varsigma}(\psi u_k)\,\leq\,\displaystyle\frac{2}{\min\{1/2,c_0/4,c^{\ast\star}\}}\left\{
L_{\psi'}\displaystyle\int^0_{-\varsigma}\|u_k(t)\|^2_{_{2,\Omega_k(t)}}\,dt\right.+$\\
\begin{equation}\label{thm1-19}
+\left.k^2\displaystyle\int^0_{-\varsigma}\displaystyle\int_{\Omega_k(t)}\left(\frac{1}{k}|f(t,x)|+\mathfrak{h}\right)\,dx\,dt\,+\,
k^2\displaystyle\int^0_{-\varsigma}\displaystyle\int_{\Gamma_k(t)}\left(\frac{1}{k}|g(t,x)|+\mathfrak{k}\right)\,d\mu\,dt\right\}.
\end{equation}
Having this, we now produce estimates in the last two integral terms in (\ref{thm1-19}). In fact,
recalling that $k\geq\hat{k}_0$ and applying H\"older's inequality, we see that
\begin{equation}\label{thm1-20}
\displaystyle\int^0_{-\varsigma}\displaystyle\int_{\Omega_k(t)}\frac{1}{k}|f(t,x)|\,dx\,dt\,\leq\,\displaystyle\frac{1}{k}
\|f\|_{_{L^{\kappa_1}(-\varsigma,0;L^{p}(\Omega))}}\left(\displaystyle\int^0_{-\varsigma}|\Omega_k(t)|^{^{\frac{\kappa_1(p-1)}{p(\kappa_1-1)}}}dt\right)
^{^{\frac{\kappa_1-1}{\kappa_1}}}
\,\leq\,\left(\displaystyle\int^0_{-\varsigma}|\Omega_k(t)|^{^{\frac{\kappa_1(p-1)}{p(\kappa_1-1)}}}dt\right)^{^{\frac{\kappa_1-1}{\kappa_1}}}.
\end{equation}
Proceeding in the exact way, we find that
\begin{equation}\label{thm1-21}
\displaystyle\int^0_{-\varsigma}\displaystyle\int_{\Omega_k(t)}\mathfrak{h}\,dx\,dt\,\leq\,\|\mathfrak{h}\|_{_{\min\left\{\frac{r_1}{2},r_3\right\},\Omega}}
\displaystyle\int^0_{-\varsigma}|\Omega_k(t)|^{2/\mathfrak{r}}dt,
\end{equation}
and
\begin{equation}\label{thm1-22}
\displaystyle\int^0_{-\varsigma}\displaystyle\int_{\Gamma_k(t)}\frac{1}{k}|g(t,x)|\,d\mu\,dt\,\leq\,
\left(\displaystyle\int^0_{-\varsigma}\mu(\Gamma_k(t))^{^{\frac{\kappa_2(q-1)}{q(\kappa_2-1)}}}dt\right)
^{^{\frac{\kappa_2-1}{\kappa_2}}},
\end{equation}
and
\begin{equation}\label{thm1-23}
\displaystyle\int^0_{-\varsigma}\displaystyle\int_{\Gamma_k(t)}\mathfrak{k}\,d\mu\,dt\,\leq\,\|\mathfrak{k}\|_{_{\min\{s,\theta\},\Gamma}}
\displaystyle\int^0_{-\varsigma}\mu(\Gamma_k(t))^{2/\mathfrak{s}}dt.
\end{equation}
Put $$\mathfrak{c}_1:=\displaystyle\frac{2}{\min\{1/2,c_0/4,c^{\ast\star}\}}\,\,\,\textrm{and}\,\,\,
\mathfrak{c}_2:=\displaystyle\frac{2\max\left\{1,\|\mathfrak{h}\|_{_{\min\{r_1,r_3\},\Omega}},
\|\mathfrak{k}\|_{_{\min\{s,\theta\},\Gamma}}\right\}}{\min\{1/2,c_0/4,c^{\ast\star}\}},$$
and we choose
$$\theta_{1,1}:=\frac{4\tilde{p}+2\tilde{\kappa}_1N-\tilde{p}\tilde{\kappa}_1N}{\tilde{p}\tilde{\kappa}_1N},\,\,\,\,\,\,\,
r_{1,1}:=(1+\theta_{1,1})\tilde{\kappa}_1,\,\,\,\,\,\,\,s_{1,1}:=(1+\theta_{1,1})\tilde{p},$$
$$\theta_{1,2}:=\frac{2N+2\mathfrak{r}-N\mathfrak{r}}{N\mathfrak{r}},\,\,\,\,\,\,\,
r_{1,2}:=2(1+\theta_{1,2}),\,\,\,\,\,\,\,s_{1,2}:=(1+\theta_{1,2})\mathfrak{r},$$
$$\theta_{2,1}:=\frac{4\tilde{q}+2\tilde{\kappa}_2d-\tilde{q}\tilde{\kappa}_2N}{\tilde{q}\tilde{\kappa}_2N},\,\,\,\,\,\,\,
r_{2,1}:=(1+\theta_{2,1})\tilde{\kappa}_2,\,\,\,\,\,\,\,s_{2,1}:=(1+\theta_{2,1})\tilde{q},$$
$$\theta_{2,2}:=\frac{2d+2\mathfrak{s}-N\mathfrak{s}}{N\mathfrak{s}},\,\,\,\,\,\,\,
r_{2,2}:=2(1+\theta_{2,2}),\,\,\,\,\,\,\,s_{2,2}:=(1+\theta_{2,2})\mathfrak{s}.$$
A straightforward calculation shows that the parameters $\theta_{1,\xi},\,\theta_{2,\zeta},\,r_{1,\xi},\,r_{2,\zeta},\,s_{1,\xi},\,s_{2,\zeta}$
($\xi,\,\zeta\in\{1,2\}$) fulfill (\ref{Lem1-01}).
Then using all these notations, and substituting (\ref{thm1-20}), (\ref{thm1-21}), (\ref{thm1-22}), and (\ref{thm1-23}) into (\ref{thm1-19}), we arrive at\\[2ex]
$\Upsilon^2_{\varsigma}(\psi u)\,\leq\,\mathfrak{c}_1L_{\psi'}\displaystyle\int^0_{-\varsigma}\|u_k(t)\|^2_{_{2,\Omega_k(t)}}\,dt+$\\
\begin{equation}\label{thm1-24}
+\mathfrak{c}_2k^2\displaystyle\sum^{2}_{\xi=1}\left(\displaystyle\int^0_{-\varsigma}|\Omega_k(t)|
^{^{\frac{r_{1,\xi}}{s_{1,\xi}}}}\,dt\right)^{^{\frac{2(1+\theta_{1,\xi})}{r_{1,\xi}}}}
+\mathfrak{c}_2k^2\displaystyle\sum^{2}_{\zeta=1}\left(\displaystyle\int^0_{-\varsigma}\mu(\Gamma_k(t))
^{^{\frac{r_{2,\zeta}}{s_{2,\zeta}}}}\,dt\right)^{^{\frac{2(1+\theta_{2,\zeta})}{r_{2,\zeta}}}}.
\end{equation}
Next, given $\varepsilon\in(0,1/2)$ fixed, choose $$\psi_{\varepsilon}(t):=\left\{
\begin{array}{lcl}
\displaystyle\frac{t+\varsigma}{\varepsilon\varsigma},\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\textrm{if}\,\,t\in[-\varsigma,-(1-\varepsilon)\varsigma],\\[2ex]
\,\,\,\,1,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\textrm{if}\,\,t\in[-(1-\varepsilon)\varsigma,0].\\
\end{array}
\right.$$
Clearly $\psi_{\varepsilon}\in H^1(-\varsigma,0)$ with $0\leq\psi_{\varepsilon}\leq1$,\, $\psi_{\varepsilon}(-\varsigma)=0$, and
$L_{\psi'_{\varepsilon}}:=\displaystyle\sup_{-\varsigma\leq t\leq0}|\psi'_{\varepsilon}(t)|\leq(\varepsilon\varsigma)^{-1}$. Moreover, we
obtain that $$\Upsilon^2_{_{(1-\varepsilon)\varsigma}}(u)\,\leq\,\Upsilon^2_{\varsigma}(\psi_{\varepsilon}u),$$
and thus letting $\gamma_0:=\max\{\mathfrak{c}_1,\mathfrak{c}_2\}$ and replacing $\psi=\psi_{\varepsilon}$ in (\ref{thm1-24}), we obtain that\\[2ex]
$\Upsilon^2_{_{(1-\varepsilon)\varsigma}}(u)\,\leq\,\displaystyle
\frac{\gamma_0}{\varepsilon\varsigma}\displaystyle\int^0_{-\varsigma}\|u_k(t)\|^2_{_{2,\Omega_k(t)}}\,dt+$\\
\begin{equation}\label{thm1-25}
+\gamma_0k^2\displaystyle\sum^{2}_{\xi=1}\left(\displaystyle\int^0_{-\varsigma}|\Omega_k(t)|
^{^{\frac{r_{1,\xi}}{s_{1,\xi}}}}\,dt\right)^{^{\frac{2(1+\theta_{1,\xi})}{r_{1,\xi}}}}
+\gamma_0k^2\displaystyle\sum^{2}_{\zeta=1}\left(\displaystyle\int^0_{-\varsigma}\mu(\Gamma_k(t))
^{^{\frac{r_{2,\zeta}}{s_{2,\zeta}}}}\,dt\right)^{^{\frac{2(1+\theta_{2,\zeta})}{r_{2,\zeta}}}}.
\end{equation}
Therefore, (\ref{thm1-25}) shows that (\ref{Lem1-02}) and all the conditions of Lemma \ref{Lem1} are fulfilled, and thus
applying Lemma \ref{Lem1} to both $u$ and $-u$ (the latter one being a weak solution of (\ref{1.06}) for $f,\,g$ replaced by
$-f,\,-g$, respectively), we establish (\ref{Thm1-01}) in the case $T\leq T_0$.\\
$\bullet$\,\, {\it \underline{Step 2}}. Assume now in addition that $u(-T)=u_0=0$. Then by choosing $\varsigma:=T$ and
and $\psi(t):=1$ for al $t\in[-T,0]$, equality (\ref{thm1-02}) becomes
\begin{equation}\label{thm1-26}
\displaystyle\frac{1}{2}\displaystyle\int_{\Omega_k(t)}|u_k(t)|^2\,dx
=\displaystyle\int^t_{-T}\left(\displaystyle\int_{\Omega_k(\xi)}u_k(\xi)\frac{ du_k(\xi)}{d\xi}\,dx\right)d\xi.
\end{equation}
From here, the calculations follow in the exact way as in the previous step, and in particular (\ref{thm1-12}) is transformed into\\[2ex]
$\min\left\{\displaystyle\frac{1}{2},\displaystyle\frac{c_0}{4},c^{\ast\star}\right\}\Upsilon^2_{_T}(u)
\,\leq\,\displaystyle\sup_{-T\leq t\leq0}\left(\displaystyle\frac{1}{2}\|u_k(t)\|^2_{_{2,\Omega_k(t)}}\right)+
\frac{c_0}{4}\displaystyle\int^0_{-T}\|\nabla u_k(t)\|^2_{_{2,\Omega_k(t)}}\,dt\,+\,c^{\ast\star}
\displaystyle\int^0_{-T}\|u_k(t)\|^2_{_{D(\Lambda_{_{\Gamma}})}}\,dt$\\
\begin{equation}\label{thm1-27}
\leq\,\displaystyle\int^0_{-T}\left(\|u_k(t)\|^2_{_{2,\Omega_k(t)}}
+\displaystyle\int_{\Omega_k(t)}\left(\frac{1}{k}|f(t,x)|+\mathfrak{h}\right)(|u_k(t)|^2+k^2)\,dx
+\displaystyle\int_{\Gamma_k(t)}\left(\frac{1}{k}|g(t,x)|+\mathfrak{k}\right)(|u_k(t)|^2+k^2)\,d\mu\right)\,dt.
\end{equation}
Continuing analogously as in the previous case, we arrive a the inequality\\[2ex]
$\Upsilon^2_{_T}(u)\,\leq\,\gamma_0\displaystyle\int^0_{-T}\|u_k(t)\|^2_{_{2,\Omega_k(t)}}\,dt+$\\
\begin{equation}\label{thm1-28}
+\gamma_0k^2\displaystyle\sum^{2}_{\xi=1}\left(\displaystyle\int^0_{-T}|\Omega_k(t)|
^{^{\frac{r_{1,\xi}}{s_{1,\xi}}}}\,dt\right)^{^{\frac{2(1+\theta_{1,\xi})}{r_{1,\xi}}}}
+\gamma_0k^2\displaystyle\sum^{2}_{\zeta=1}\left(\displaystyle\int^0_{-T}\mu(\Gamma_k(t))
^{^{\frac{r_{2,\zeta}}{s_{2,\zeta}}}}\,dt\right)^{^{\frac{2(1+\theta_{2,\zeta})}{r_{2,\zeta}}}},
\end{equation}
where all the constants and parameters appearing in (\ref{thm1-28}) are defined as in the previous step. Consequently,
(\ref{Lem1-04}) is valid for this case, and another application of Lemma \ref{Lem1} gives (\ref{Thm1-02}).
This completes the proof of Theorem \ref{Thm-Partial-Bounded} in the case when the weak solution
$u\in C(0,T;L^2(\Omega))\cap L^2(0,T;\mathcal{W}_2(\Omega;\Gamma))$ of (\ref{1.06}) is also a
classical solution of (\ref{1.06}), and for $T\leq T_0$.\\
$\bullet$\,\, {\it \underline{Step 3}}. We now prove the general case. Since the proof runs in a similar way as in
\cite[proof of Proposition 3.1]{NITTKA2014}, we will only sketch the main ingredients of the proof. Let
$u\in C(0,T;L^2(\Omega))\cap L^2(0,T;\mathcal{W}_2(\Omega;\Gamma))$ be a weak solution of problem (\ref{1.06}). Since $D(A_{\mu})$ is dense
in $L^2(\Omega)$, we pick $\{u_{0,n}\}\subseteq D(A^2_{\mu})$ such that $u_{0,n}\stackrel{n\rightarrow\infty}{\longrightarrow}u_0$ in $L^2(\Omega)$.
We also take sequences $\{f_n\}\subseteq C^2([0,T];L^{\infty}(\Omega))$ and $\{g_n\}\subseteq C^2([0,T];L^{\infty}_{\mu}(\Gamma))$
fulfilling $f_{n}\stackrel{n\rightarrow\infty}{\longrightarrow}f$ in $L^{\kappa_1}(0,T;L^p(\Omega))$ and
$g_{n}\stackrel{n\rightarrow\infty}{\longrightarrow}g$ in $L^{\kappa_2}(0,T;L^q_{\mu}(\Gamma))$, and $f_n(0,x)=g_n(0,x)=0$ for every $n\in\mathbb{N\!}\,$.
Using $f_n,\,g_n$ as the data functions in problem (\ref{1.06}), from an application of Theorem \ref{reg-sol-class}, Theorem \ref{exist-uniq-weak-soln},
and Corollary \ref{coincidence}, we get that problem (\ref{1.06}) (with data $f_n,\,g_n$) admits a unique classical solution
$u_n$, and $u_{n}\stackrel{n\rightarrow\infty}{\longrightarrow}u$ in $C([0,T];L^2(\Omega))\cap L^2(0,T;\mathcal{W}_2(\Omega;\Gamma))$.
Then, given $T>0$ arbitrary, put $T'_0:=\min\{T_0,T\}>0$, for $T_0>0$ the parameter given in the previous two steps, and let $I'\subseteq[T'_0/2,T'_0]$ be an interval.
Then the inequality (\ref{Thm1-01}) is valid (over $I'$) for the function $u_n$ (with data $f_n,\,g_n$), and moreover an application of (\ref{Thm1-01}) to
the function $u_n-u_m$ ($n,\,m\in\mathbb{N\!}\,$) shows that $\{u_n\}$ is a Cauchy sequence in $L^{\infty}(I';L^{\infty}(\Omega))$. Thus
$u_{n}\stackrel{n\rightarrow\infty}{\longrightarrow}u$ over $L^{\infty}(I';L^{\infty}(\Omega))$. Therefore, passing to the limit and
using the fact that $[T/2,T]\subseteq\displaystyle\bigcup^m_{j=1}I'_i$ (for some $m\in\mathbb{N\!}\,$) with $\ell(I'_i)\leq L'_0/2$, we are lead into the fulfillment
of the inequality (\ref{Thm1-01}). If in addition $u_0=0$, then the same procedure is repeated over the inequality (\ref{Thm1-02}), and this
completes the proof of the theorem.

\label{infitiny-u_0-infinity}
Suppose that conditions {\bf (A3)'} and {\bf (B4)'} hold.
Given $T>0$ arbitrary fixed, let $\kappa_1,\,\kappa_2,\,p,\,q\in[2,\infty)$ be such that
\begin{equation}\label{Thm2-00}
\displaystyle\frac{1}{\kappa_1}+\displaystyle\frac{N}{2p}<1\,\,\,\,\,\,\,\,\textrm{and}
\,\,\,\,\,\,\,\,\displaystyle\frac{1}{\kappa_2}+\displaystyle\frac{d}{2q(d+2-N)}<\frac{1}{2}.
\end{equation}
Given $u_0\in L^{\infty}(\Omega)$, let $f\in L^{\kappa_1}(0,T;L^p(\Omega))$ and $g\in L^{\kappa_2}(0,T;L^q_{\mu}(\Gamma))$, and
let $u\in C(0,T;L^2(\Omega))\cap L^2(0,T;\mathcal{W}_2(\Omega;\Gamma))$ be a weak solution of problem (\ref{1.06}).
Then there exists a constant $C^{\ast}_2=C^{\ast}_2(T,N,d,\kappa_1,\kappa_2,p,q,|\Omega|,\mu(\Gamma))>0$ such that
\begin{equation}\label{Thm2-01}
\|u\|_{_{L^{\infty}(0,T;L^{\infty}(\Omega))}}
\,\leq\,C^{\ast}_2\left(\|u_0\|_{_{\infty,\Omega}}+\|f\|_{_{L^{\kappa_1}(0,T;L^{p}(\Omega))}}+
\|g\|_{_{L^{\kappa_2}(0,T;L^{q}_{\mu}(\Gamma))}}\right).
\end{equation}

If $u\in C(0,T;L^2(\Omega))\cap L^2(0,T;\mathcal{W}_2(\Omega;\Gamma))$ solves (\ref{1.06}), then by linearity one can write $u(t):=T_{\mu}(t)u_0+\tilde{u}(t)$,
where $T_{\mu}(t)u_0$ denotes the weak solution of the homogeneous problem (\ref{1.06}) for $f=g=0$ (recall Corollary \ref{coincidence}),
and $\tilde{u}(t)$ solves (\ref{1.06}) for $u_0=0$. Then an application of (\ref{infinity-semigroup}) together with (\ref{Thm1-02}) entail that\\[2ex]
$\|u\|^2_{_{L^{\infty}(0,T;L^{\infty}(\Omega))}}\,\leq\,2\left(\displaystyle\sup_{t\in[0,T]}\|T_{\mu}(t)u_0\|^2_{_{\infty,\Omega}}
+\|\tilde{u}\|^2_{_{L^{\infty}(0,T;L^{\infty}(\Omega))}}\right)$\\
\begin{equation}\label{Thm2-02}
\leq\,2\left\{M^2e^{2|\omega|T}\|u_0\|^2_{_{\infty,\Omega}}+C^{\ast}_1\left(\|\tilde{u}\|_{_{L^{2}(0,T;L^{2}(\Omega))}}+
\|f\|_{_{L^{\kappa_1}(0,T;L^{p}(\Omega))}}+\|g\|_{_{L^{\kappa_2}(0,T;L^{q}_{\mu}(\Gamma))}}\right)\right\}.
\end{equation}
Furthermore, an application of Proposition \ref{apriori estimates} with Remark \ref{approx-classical} and H\"older's inequality gives that
\begin{equation}\label{Thm2-03}
\|\tilde{u}\|_{_{L^{2}(0,T;L^{2}(\Omega))}}
\leq\,cT\left(\|u_0\|^2_{_{\infty,\Omega}}+
\|f\|_{_{L^{\kappa_1}(0,T;L^{p}(\Omega))}}+\|g\|_{_{L^{\kappa_2}(0,T;L^{q}_{\mu}(\Gamma))}}\right),
\end{equation}
for some constant $c>0$.
Combining (\ref{Thm2-02}) and (\ref{Thm2-03}) yield the inequality (\ref{Thm2-01}), as asserted.

\label{infitiny-u_0-L2}
Suppose that conditions {\bf (A3)'} and {\bf (B4)'} hold.
Given $T_2>T_1>0$ arbitrary fixed, let $\kappa_1,\,\kappa_2,\,p,\,q\in[2,\infty)$ be as in Theorem \ref{infitiny-u_0-infinity}.
Given $u_0\in L^{2}(\Omega)$, let $f\in L^{\kappa_1}(0,T;L^p(\Omega))$ and $g\in L^{\kappa_2}(0,T;L^q_{\mu}(\Gamma))$, and
let $u\in C(0,T;L^2(\Omega))\cap L^2(0,T;\mathcal{W}_2(\Omega;\Gamma))$ be a weak solution of problem (\ref{1.06}).
Then there exists a constant $C^{\ast}_3=C^{\ast}_3(T_1,T_2,N,d,\kappa_1,\kappa_2,p,q,|\Omega|,\mu(\Gamma))>0$ such that
\begin{equation}\label{Thm3-01}
|\|\mathbf{u}\||_{_{L^{\infty}(T_1,T_2;\mathbb{X\!}^{\,\infty}(\Omega;\Gamma))}}
\,\leq\,C^{\ast}_3\left(\|u_0\|_{_{2,\Omega}}+\|f\|_{_{L^{\kappa_1}(0,T;L^{p}(\Omega))}}+
\|g\|_{_{L^{\kappa_2}(0,T;L^{q}_{\mu}(\Gamma))}}\right).
\end{equation}

If $u\in C(0,T;L^2(\Omega))\cap L^2(0,T;\mathcal{W}_2(\Omega;\Gamma))$ is a weak solution of (\ref{1.06}), then by using the fact that $[T_1,T_2]\subseteq\displaystyle\bigcup^m_{j=1}[T^{\ast}_j/2,T^{\ast}_j]$
with $T^{\ast}_1<T^{\ast}_2<\ldots<T^{\ast}_m$ (for some $m\in\mathbb{N\!}\,$), and $T^{\ast}_1=T_1$, \,$T^{\ast}_m=T_2$,
one can the full strength of Theorem \ref{Thm-Partial-Bounded} to get that
\begin{equation}\label{Thm3-02}
|\|\mathbf{u}\||_{_{L^{\infty}(T_1,T_2;\mathbb{X\!}^{\,\infty}(\Omega;\Gamma))}}
\,\leq\,C^{\ast}_1\left(\|u\|_{_{L^{2}(0,T;L^{2}(\Omega))}}+\|f\|_{_{L^{\kappa_1}(0,T;L^{p}(\Omega))}}+
\|g\|_{_{L^{\kappa_2}(0,T;L^{q}_{\mu}(\Gamma))}}\right).
\end{equation}
Moreover, an application of Proposition \ref{apriori estimates} with Remark \ref{approx-classical} and H\"older's inequality gives that
\begin{equation}\label{Thm3-03}
\|u\|_{_{L^{2}(0,T;L^{2}(\Omega))}}
\leq\,c'\left(\|u_0\|^2_{_{2,\Omega}}+
\|f\|_{_{L^{\kappa_1}(0,T;L^{p}(\Omega))}}+\|g\|_{_{L^{\kappa_2}(0,T;L^{q}_{\mu}(\Gamma))}}\right).
\end{equation}
for some constant $c'>0$.
Combining (\ref{Thm3-02}) and (\ref{Thm3-03}) gives (\ref{Thm3-01}), as desired.

